// agent-map: a live map of the session's subagents and how they connect,
// and (0.3.0) a deck that caps how many agents a session spawns, tracks what
// their results cost the main context, and logs each agent's lifecycle.
//
// agent.spawn refuses a spawn past a cap (concurrent, per turn, per session)
// unless the person allows it from a `[cap-override: <reason>]` ask.
//
// Every hook here observes and passes its event on, with two exceptions the
// person asks for: the pane's Stop button (TaskStop, on a confirmed second
// press) and, when TaskStop can't stop an agent, the mute that refuses that
// agent's further tool calls. The data a drawing
// depends on lives in $.state (it survives a hot reload); the band's on/off
// switch is also kept in $.store so it lasts between sessions.
//
// 0.4.0: the pane opens on the Agents cards (hooks/pane.ts, drawn with the kit):
// session tiles (cost, tokens, time), one card per agent with its role doodle, model and
// effort, TodoWrite progress, ctx %, tokens, cost and elapsed time, and the planned spawns.
import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { AgentRecord, CapConfig, CapCounters, CapSources, LogEntry, LogKind, PaneView, PendingCall, PriceRow } from '../types'
import {
  ASK_ALLOW_ONE,
  ASK_ALLOW_TURN,
  ASK_DENY,
  CAP_USAGE,
  DEFAULT_CAPS,
  DEFAULT_SOURCES,
  MAIN,
  SETTING_KEY,
  addLog,
  addReturned,
  askText,
  capBreach,
  capKeyOf,
  capMaxOf,
  capNear,
  capUses,
  denyText,
  estimateTokens,
  layerCaps,
  mergeCaps,
  nearText,
  newTurn,
  overrideReason,
  parseCapCommand,
  parseCapFile,
  parseCapReset,
  resultText,
  runningCount,
  settingProblem,
  settingValues,
  settingsCaps,
  stripOverride,
  totalTokens,
  zeroCounters,
  MUTE_REASON,
  activityOf,
  activityOfMessages,
  effortOf,
  todoOf,
  addEdge,
  addWaiting,
  addPending,
  anyRunning,
  applyComplete,
  applySpawn,
  applyStep,
  applyToolCall,
  clearFinished,
  clearWaiting,
  isStuck,
  idleMs,
  markFailed,
  markMuted,
  markStopped,
  reconcile,
  pendingOf,
  resolveAddress,
  resume,
  spawnFacts,
  statusOfComplete,
  str,
  takePending,
  withAgent,
  withOrder,
} from './model'
import type { Agents, CapCommandKind, ListedAgent } from './model'
import {
  DEFAULT_STUCK_MS,
  bandOf,
  buildRows,
  cardsText,
  cut,
  fmtElapsed,
  fmtIdle,
  fmtTokens,
  elapsedOf,
  labelOf,
  logRows,
  logText,
  returnedNear,
  returnedNote,
  teamRows,
  teamText,
  treeText,
} from './format'
import type { Row } from './format'
import { TONES, makeKit } from './kit'
import type { Elements } from './kit'
import { DEFAULT_WINDOW, capsTree, cardsTree, headerTree, mainRow } from './pane'
import { PRICES, mergePrices } from './prices'

const PANE = 'agent-map'
const TITLE = 'Agent map'
const COMMAND = 'agent-map'
const BAND_KEY = 'band'

const agentsAtom = atom({ plugin: 'lk-agent-map', key: 'agents' } as const, {} as Record<string, AgentRecord>)
const orderAtom = atom({ plugin: 'lk-agent-map', key: 'order' } as const, [] as string[])
const pendingAtom = atom({ plugin: 'lk-agent-map', key: 'pending' } as const, [] as PendingCall[])
const expandedAtom = atom({ plugin: 'lk-agent-map', key: 'expanded' } as const, [] as string[])
const nowAtom = atom({ plugin: 'lk-agent-map', key: 'now' } as const, 0)
const bandAtom = atom({ plugin: 'lk-agent-map', key: 'band' } as const, true)
const everAtom = atom({ plugin: 'lk-agent-map', key: 'everSpawned' } as const, false)
const armedAtom = atom({ plugin: 'lk-agent-map', key: 'armed' } as const, null as string | null)
const capsAtom = atom({ plugin: 'lk-agent-map', key: 'caps' } as const, DEFAULT_CAPS as CapConfig)
const capSourcesAtom = atom({ plugin: 'lk-agent-map', key: 'capSources' } as const, DEFAULT_SOURCES as CapSources)
const countersAtom = atom({ plugin: 'lk-agent-map', key: 'counters' } as const, zeroCounters() as CapCounters)
const logAtom = atom({ plugin: 'lk-agent-map', key: 'log' } as const, [] as LogEntry[])
const viewAtom = atom({ plugin: 'lk-agent-map', key: 'view' } as const, null as PaneView | null)
const showLogAtom = atom({ plugin: 'lk-agent-map', key: 'showLog' } as const, false)
const collapsedAtom = atom({ plugin: 'lk-agent-map', key: 'collapsed' } as const, false)
const windowAtom = atom({ plugin: 'lk-agent-map', key: 'window' } as const, DEFAULT_WINDOW)
const pricesAtom = atom({ plugin: 'lk-agent-map', key: 'prices' } as const, PRICES as PriceRow[])

const CAPS_KEY = 'caps'
// 0.5.0 reads the chosen view from a new key, so everyone lands on cards once; later choices are kept
const VIEW_KEY = 'view2'
const CAP_FILE = '.claude/agent-map.json'
const VIEWS: readonly PaneView[] = ['tree', 'cards', 'team']

/** How long an armed Stop button waits for its second press. */
export const ARM_MS = 5000
/** Room the pane keeps on a running row for its Stop button. */
const STOP_RESERVE = 16
/** An agent's own transcript is read for its last activity at most this often. */
const PEEK_MS = 10_000
const STOPPED_BY_YOU = 'you (agent map)'

type Config = { stuckAfterMs: number }
export function parseConfig(options: unknown): Config {
  const o = (options && typeof options === 'object' ? options : {}) as Record<string, unknown>
  const v = o.stuckAfterMs
  const stuckAfterMs = typeof v === 'number' && Number.isFinite(v) && v >= 0 ? Math.round(v) : DEFAULT_STUCK_MS
  return { stuckAfterMs }
}
let cfg: Config = parseConfig(undefined)
// The values register(on, options) got: the cap settings when $.config.list() can't be read.
let regOptions: unknown

// tool.check carries no loop id; the tool.call around it does, keyed by the call's id.
const callLoop = new Map<string, string>()
// TaskStop calls this mod raised itself, by task id: not counted as the main loop's tools.
const ownStops = new Set<string>()
// When each agent's transcript was last read for its activity.
const peekedAt = new Map<string, number>()
let armTimer: { cancel: () => void } | null = null
// Spawns the cap gate admitted that agent.spawn hasn't recorded yet, by tool_use_id: they count as running.
const inflight = new Set<string>()
// The cap note each admitted spawn logs with ("running 2/4 · turn 1/8 · session 1/40").
const spawnNotes = new Map<string, string>()
// Agent tool calls and the agents they started, both ways, so a result finds its agent whichever comes first.
const agentOfCall = new Map<string, string>()
const returnedOfCall = new Map<string, number>()
let spawnSeq = 0
// Permission asks not yet shown as waiting: an auto-approved ask resolves inside the grace and never flickers.
type PendingAsk = { loop: string; tool: string; timer: { cancel: () => void } | null }
const pendingAsks = new Map<string, PendingAsk>()
// Once classic.PermissionRequest has fired in this session, a dialog is the signal and the grace timer only stands by.
let dialogSignal = false
// The session's working directory, for <cwd>/.claude/agent-map.json
let sessionCwd: string | undefined
// The cap gate runs one spawn at a time, so parallel spawns can't all pass the same count.
let gateChain: Promise<unknown> = Promise.resolve()
function serialized<T>(fn: () => Promise<T>): Promise<T> {
  const run = gateChain.then(fn, fn)
  gateChain = run.catch(() => undefined)
  return run
}

// The one-second redraw timer. Timers stop when the module reloads, so this
// is module state on purpose: a fresh module starts its own when needed.
let ticker: { cancel: () => void } | null = null

type Api = Parameters<typeof read>[0]

async function nowOf($: Api): Promise<number> {
  try {
    const t = await $.clock.now()
    return typeof t === 'number' ? t : Date.now()
  } catch {
    return Date.now()
  }
}

async function tick($: Api): Promise<void> {
  try {
    const t = await $.clock.now()
    await update($, nowAtom, () => t)
    await reconcileList($)
    await alertStuck($, t)
    if (!anyRunning(await read($, agentsAtom)) && ticker) {
      ticker.cancel()
      ticker = null
    }
  } catch {
    // A failed tick waits for the next one
  }
}

/** Starts the redraw timer while anything runs, and stops it when nothing does. */
async function syncTicker($: Api): Promise<void> {
  try {
    const running = anyRunning(await read($, agentsAtom))
    if (running && !ticker) {
      ticker = $.clock.every(1000, () => {
        void tick($)
      })
    } else if (!running && ticker) {
      ticker.cancel()
      ticker = null
    }
  } catch {
    ticker = null
  }
}

/** Toasts once per stall for each running agent idle past stuckAfterMs. */
async function alertStuck($: Api, now: number): Promise<void> {
  if (cfg.stuckAfterMs <= 0) return
  const agents = await read($, agentsAtom)
  const stuck = Object.values(agents).filter(a => a.id !== MAIN && !a.stuckNotified && isStuck(a, now, cfg.stuckAfterMs))
  if (stuck.length === 0) return
  await update($, agentsAtom, (m: Agents) => {
    let out = m
    for (const a of stuck) if (out[a.id]) out = { ...out, [a.id]: { ...out[a.id], stuckNotified: true } }
    return out
  })
  for (const a of stuck) {
    await logEvent($, a.id, 'idle', 'no tool call or model request for ' + fmtIdle(idleMs(a, now))).catch(() => undefined)
    try {
      await $.ui.toast('Agent ' + cut(labelOf(a), 40) + ' has been idle ' + fmtIdle(idleMs(a, now)) + ': no tool call or model request')
    } catch {
      // The row still shows ⚠ idle
    }
  }
}

/**
 * Merges $.agent.list() into the map, when this build has it: agents the
 * spawn hook missed (forks, teammates, workflow agents) appear, parents and
 * end states fill in. An agent with no activity yet gets its transcript's tail.
 */
async function reconcileList($: Api): Promise<void> {
  let listed: unknown
  try {
    listed = await $.agent.list()
  } catch {
    // A build or host without the list: the spawn hook's map stands
    return
  }
  if (!Array.isArray(listed) || listed.length === 0) return
  const now = await nowOf($)
  const order = await read($, orderAtom)
  let added: string[] = []
  let nextOrder = order
  await update($, agentsAtom, (m: Agents) => {
    const r = reconcile(m, order, listed as ListedAgent[], now)
    added = r.added
    nextOrder = r.order
    return r.agents
  })
  if (nextOrder !== order) await update($, orderAtom, () => nextOrder)
  if (added.length > 0) {
    await openOnFirstSpawn($)
    await syncTicker($)
  }
  await peekActivity($, now)
}

/** The last activity of running agents no tool.call was seen from, from their own transcripts. */
async function peekActivity($: Api, now: number): Promise<void> {
  const agents = await read($, agentsAtom)
  for (const a of Object.values(agents)) {
    if (a.id === MAIN || !a.isSpawned || a.status !== 'running' || a.activity) continue
    if (now - (peekedAt.get(a.id) ?? -Infinity) < PEEK_MS) continue
    peekedAt.set(a.id, now)
    try {
      const activity = activityOfMessages(await $.session.messages({ agentId: a.id }))
      if (activity) await update($, agentsAtom, (m: Agents) => (m[a.id] && !m[a.id].activity ? { ...m, [a.id]: { ...m[a.id], activity } } : m))
    } catch {
      // A transcript this session can't read: the row shows no activity
    }
  }
}

async function changeAgent($: Api, id: string, fn: (a: AgentRecord, now: number) => AgentRecord): Promise<void> {
  const now = await nowOf($)
  await update($, agentsAtom, (m: Agents) => withAgent(m, id, now, a => fn(a, now)))
  await update($, nowAtom, () => now)
}

/** Shows ⏸ waiting for a pending ask now (its grace ran out, or a dialog opened for it). */
// An ask waits out its grace: when the grace runs out it shows ⏸ waiting, unless a dialog signal says it was approved.
function armGrace($: Api, toolUseId: string, grace: number): void {
  const p = pendingAsks.get(toolUseId)
  if (!p) return
  p.timer = $.clock.after(grace, () => {
    if (p.timer === null) return
    p.timer = null
    // With a dialog signal in this session, an ask the grace outlived without a dialog was approved: it runs
    if (dialogSignal) pendingAsks.delete(toolUseId)
    else void markWaiting($, toolUseId).catch(() => undefined)
  })
}

// The call a settings PreToolUse point saw is going to run: its pending ask is dropped and a shown ⏸ waiting clears.
async function clearApprovedWait($: Api, e: unknown): Promise<void> {
  let toolUseId = str(e, 'tool_use_id')
  if (!toolUseId) {
    const tool = str(e, 'tool_name', 'tool')
    for (const [k, p] of pendingAsks) if (p.tool === tool && p.loop === (str(e, 'agentId', 'agent_id') ?? MAIN)) toolUseId = k
  }
  if (!toolUseId) return
  const id = toolUseId
  cancelAsk(id)
  let waited: string[] = []
  await update($, agentsAtom, (m: Agents) => {
    waited = Object.values(m).filter(a => a.waiting?.some(w => w.toolUseId === id)).map(a => a.id)
    return clearWaiting(m, id)
  })
  for (const w of waited) await logEvent($, w, 'resumed', 'approved: ' + (str(e, 'tool', 'tool_name') ?? 'tool'))
}

async function markWaiting($: Api, toolUseId: string): Promise<void> {
  const p = pendingAsks.get(toolUseId)
  if (!p) return
  pendingAsks.delete(toolUseId)
  p.timer?.cancel()
  const a = (await read($, agentsAtom))[p.loop]
  if (p.loop !== MAIN && a && a.status !== 'running') return
  await changeAgent($, p.loop, (x, now) => addWaiting(x, { toolUseId, tool: p.tool, at: now }))
  await logEvent($, p.loop, 'waiting', p.tool)
}

function cancelAsk(toolUseId: string): void {
  const p = pendingAsks.get(toolUseId)
  if (!p) return
  p.timer?.cancel()
  pendingAsks.delete(toolUseId)
}

function cancelAsksOf(loop: string): void {
  for (const [k, p] of pendingAsks) if (p.loop === loop) cancelAsk(k)
}

/** Appends one lifecycle event of agent `id` to the log. */
async function logEvent($: Api, id: string, kind: LogKind, text: string, label?: string): Promise<void> {
  const now = await nowOf($)
  const agents = await read($, agentsAtom)
  const name = label ?? (id === MAIN ? 'main' : cut(labelOf(agents[id], id), 32))
  await update($, logAtom, (l: LogEntry[]) => addLog(l, { at: now, id, label: name, kind, text }))
}

async function readText($: Api, path: string): Promise<string | undefined> {
  try {
    const t = await $.fs.read(path)
    return typeof t === 'string' ? t : undefined
  } catch {
    return undefined
  }
}

/**
 * The caps: defaults, then the plugin's settings (its /config rows, read live), then
 * ~/.claude/agent-map.json, then <cwd>/.claude/agent-map.json, then what /agent-map cap saved.
 * The same files' `prices` objects lay over the price table by family.
 */
async function loadCaps($: Api): Promise<void> {
  let prices: PriceRow[] = PRICES.map(r => [...r] as PriceRow)
  let rows: unknown
  try {
    rows = await $.config.list()
  } catch {
    // No rows: the values register got stand
  }
  let home: string | undefined
  try {
    home = (await $.env.get('HOME')) || undefined
  } catch {
    home = undefined
  }
  const userFile = home ? parseCapFile(await readText($, home.replace(/\/+$/, '') + '/' + CAP_FILE)) : undefined
  const projectFile = parseCapFile(await readText($, sessionCwd ? sessionCwd.replace(/\/+$/, '') + '/' + CAP_FILE : CAP_FILE))
  for (const f of [userFile, projectFile]) {
    if (f && typeof f === 'object') prices = mergePrices(prices, (f as Record<string, unknown>).prices)
  }
  let saved: unknown
  try {
    saved = await $.store.get(CAPS_KEY)
  } catch {
    // No store: the files, settings and defaults stand
  }
  const { caps, sources } = layerCaps([
    { source: 'settings', over: settingsCaps(settingValues(rows, regOptions)) },
    { source: 'user file', over: userFile },
    { source: 'project file', over: projectFile },
    { source: 'saved (/agent-map cap)', over: saved },
  ])
  await update($, capsAtom, () => caps)
  await update($, capSourcesAtom, () => sources)
  await update($, pricesAtom, () => prices)
}

/** The session's context window, which the cards' ctx % divides by (a subagent's own isn't exposed). */
async function loadWindow($: Api): Promise<void> {
  try {
    const u = (await $.session.usage()) as { context?: { window?: unknown } } | undefined
    const w = u?.context?.window
    if (typeof w === 'number' && Number.isFinite(w) && w > 0) await update($, windowAtom, () => w)
  } catch {
    // Keep the 200k fallback
  }
}

/** Drops an Agent call that will never spawn (refused by the gate or the engine) from the planned list. */
async function dropPending($: Api, toolUseId: string | undefined): Promise<void> {
  if (!toolUseId) return
  await update($, pendingAtom, (l: PendingCall[]) => (l.some(p => p.toolUseId === toolUseId) ? l.filter(p => p.toolUseId !== toolUseId) : l))
}

async function loadView($: Api): Promise<void> {
  try {
    const v = await $.store.get(VIEW_KEY)
    if (typeof v === 'string' && (VIEWS as readonly string[]).includes(v)) await update($, viewAtom, () => v as PaneView)
  } catch {
    // Keep the default: cards in the pane, the tree in /agent-map text
  }
}

async function setView($: Api, v: PaneView): Promise<void> {
  await update($, viewAtom, () => v)
  try {
    await $.store.set(VIEW_KEY, v)
  } catch {
    // Kept for this session only
  }
}

/**
 * The cap check for one spawn. Returns a refusal, or null when the spawn may
 * start (it then counts as running until agent.spawn records it).
 */
async function gate($: Api, e: Record<string, unknown>, key: string): Promise<string | null> {
  const countsTurn = e.isTeammate !== true && e.fork !== true
  const caps = await read($, capsAtom)
  const counters = await read($, countersAtom)
  const agents = await read($, agentsAtom)
  const running = runningCount(agents) + inflight.size
  const uses = capUses(running, counters, caps)
  const label = cut(stripOverride(str(e, 'description', 'name') ?? 'agent'), 32) || 'agent'
  const breach = capBreach(uses, countsTurn)
  if (breach) {
    let allowed = counters.overrideTurn
    let why = ''
    if (allowed) {
      await logEvent($, key, 'override', 'past the ' + breach.kind + ' cap (' + breach.n + '/' + breach.max + '): allowed for the rest of the turn', label)
    } else {
      const reason = overrideReason(e.description, e.prompt)
      if (!reason) {
        why = ''
      } else {
        let answer: string | undefined
        try {
          answer = await $.ui.ask(askText(reason), [ASK_ALLOW_ONE, ASK_ALLOW_TURN, ASK_DENY])
        } catch {
          answer = undefined
        }
        if (answer === ASK_ALLOW_ONE || answer === ASK_ALLOW_TURN) {
          allowed = true
          if (answer === ASK_ALLOW_TURN) await update($, countersAtom, (c: CapCounters) => ({ ...c, overrideTurn: true }))
        } else {
          why = answer === undefined ? ' No one could be asked about the override.' : ' The user declined the override.'
        }
        await logEvent($, key, 'override', reason + ': ' + (answer === undefined ? 'no one to ask, denied' : answer), label)
      }
    }
    if (!allowed) {
      await update($, countersAtom, (c: CapCounters) => ({ ...c, deniedThisTurn: true }))
      await logEvent($, key, 'denied', breach.kind + ' cap ' + breach.n + '/' + breach.max, label)
      return denyText(breach) + why
    }
  }
  inflight.add(key)
  let after = counters
  await update($, countersAtom, (c: CapCounters) => {
    after = { ...c, turn: c.turn + (countsTurn ? 1 : 0), session: c.session + 1 }
    return after
  })
  spawnNotes.set(
    key,
    'running ' + (running + 1) + capOf(caps.maxConcurrent) + ' · turn ' + after.turn + capOf(caps.maxPerTurn) + ' · session ' + after.session + capOf(caps.maxPerSession) + (countsTurn ? '' : ' · not counted per turn'),
  )
  const near = capNear(uses, caps.warnAt, countsTurn)
  if (near && !after.warnedThisTurn) {
    await update($, countersAtom, (c: CapCounters) => ({ ...c, warnedThisTurn: true }))
    try {
      await $.ui.toast(nearText(near))
    } catch {
      // The band's chip says near cap anyway
    }
  }
  return null
}

const capOf = (max: number) => (max > 0 ? '/' + max : '')

/** A spawn that next() refused or that never started gives back what the gate counted. */
async function ungate($: Api, key: string, e: Record<string, unknown>): Promise<void> {
  const countsTurn = e.isTeammate !== true && e.fork !== true
  inflight.delete(key)
  spawnNotes.delete(key)
  await update($, countersAtom, (c: CapCounters) => ({ ...c, turn: Math.max(0, c.turn - (countsTurn ? 1 : 0)), session: Math.max(0, c.session - 1) }))
}

/** What an Agent tool call's result put into its caller's context (characters / 4). */
async function noteReturned($: Api, toolUseId: string, caller: string, tokens: number): Promise<void> {
  if (tokens <= 0) return
  const agentId = agentOfCall.get(toolUseId)
  if (agentId) {
    await changeAgent($, agentId, a => addReturned(a, tokens))
    await logEvent($, agentId, 'returned', fmtTokens(tokens) + ' tok to ' + (caller === MAIN ? 'main' : cut(labelOf((await read($, agentsAtom))[caller], caller), 24)))
  } else {
    returnedOfCall.set(toolUseId, (returnedOfCall.get(toolUseId) ?? 0) + tokens)
  }
  if (caller === MAIN) await addToMain($, tokens)
}

async function addToMain($: Api, tokens: number): Promise<void> {
  const caps = await read($, capsAtom)
  let after = await read($, countersAtom)
  await update($, countersAtom, (c: CapCounters) => {
    after = { ...c, returnedTotal: c.returnedTotal + tokens }
    return after
  })
  if (!after.returnedWarned && returnedNear(caps, after)) {
    await update($, countersAtom, (c: CapCounters) => ({ ...c, returnedWarned: true }))
    try {
      await $.ui.toast(
        'agent-map: subagent results have put ' + fmtTokens(after.returnedTotal) + ' tokens into the main context. Consider /compact, or a handoff to a fresh session.',
      )
    } catch {
      // The band's chip says near cap
    }
  }
}

async function loadBand($: Api): Promise<void> {
  try {
    const saved = await $.store.get(BAND_KEY)
    if (typeof saved === 'boolean') await update($, bandAtom, () => saved)
  } catch {
    // No store: keep the default
  }
}

async function openOnFirstSpawn($: Api): Promise<void> {
  if (await read($, everAtom)) return
  await update($, everAtom, () => true)
  try {
    const placed = await $.ui.open({ id: PANE, title: TITLE })
    if (!placed || placed.isPlaced !== true) await $.ui.toast('Subagents started: /agent-map shows the map')
  } catch {
    // A pane that can't open leaves the band and /agent-map text
  }
}

async function recordSpawn($: Api, e: unknown, r: unknown, threw = false, gateKey?: string): Promise<void> {
  if (r && typeof r === 'object' && (r as { deny?: unknown }).deny) return
  let match: PendingCall | undefined
  await update($, pendingAtom, (list: PendingCall[]) => {
    const taken = takePending(list, e)
    match = taken.match
    return taken.rest
  })
  const facts = spawnFacts(e, r, match)
  const toolUseId = str(e, 'tool_use_id')
  const key = gateKey ?? toolUseId ?? ''
  const early = toolUseId ? (returnedOfCall.get(toolUseId) ?? 0) : 0
  await changeAgent($, facts.id, (a, now) => {
    let x = threw ? markFailed(applySpawn(a, facts, now), now) : applySpawn(a, facts, now)
    if (early > 0) x = addReturned(x, early)
    return x
  })
  // Recorded: it counts through the map now, no longer as in flight
  inflight.delete(key)
  if (toolUseId) {
    agentOfCall.set(toolUseId, facts.id)
    returnedOfCall.delete(toolUseId)
  }
  const a = (await read($, agentsAtom))[facts.id]
  const note = spawnNotes.get(key)
  spawnNotes.delete(key)
  await logEvent($, facts.id, 'spawned', [a ? (a.name || 'agent') + ' ' + (a.model || '?') : '', note ?? '', threw ? 'failed to start' : ''].filter(Boolean).join(' · '))
  await update($, orderAtom, (o: string[]) => withOrder(o, facts.id))
  await openOnFirstSpawn($)
  await syncTicker($)
}

async function recordComplete($: Api, e: unknown, failed: boolean): Promise<void> {
  const id = str(e, 'agentId')
  cancelAsksOf(id ?? MAIN)
  if (!id) {
    const now = await nowOf($)
    await update($, nowAtom, () => now)
    return
  }
  const status = failed ? 'failed' : statusOfComplete(e)
  const wasRunning = (await read($, agentsAtom))[id]?.status === 'running'
  const prices = await read($, pricesAtom)
  await changeAgent($, id, (a, now) => (failed ? markFailed(a, now) : applyComplete(a, e, now, status, prices)))
  const a = (await read($, agentsAtom))[id]
  if (wasRunning && a && a.isSpawned && a.status !== 'running') {
    const ret = returnedNote(await read($, agentsAtom), a)
    const kind: LogKind = a.status === 'done' || a.status === 'failed' || a.status === 'aborted' ? a.status : 'stopped'
    await logEvent($, id, kind, 'in ' + fmtElapsed(elapsedOf(a, await nowOf($))) + ' · ' + fmtTokens(totalTokens(a.tokens)) + ' tok' + (ret ? ' · ' + ret : ''))
  }
  await syncTicker($)
}

async function recordMessage($: Api, fromRaw: unknown, toRaw: unknown): Promise<void> {
  const agents = await read($, agentsAtom)
  const from = resolveAddress(agents, fromRaw) ?? MAIN
  const to = resolveAddress(agents, toRaw)
  if (!to || to === from) return
  const isSub = (id: string) => id !== MAIN && agents[id]?.isSpawned === true
  if (!isSub(from) && !isSub(to)) return
  const now = await nowOf($)
  await update($, agentsAtom, (m: Agents) => addEdge(withAgent(m, MAIN, now, a => a), from, to, now))
}

async function clearFinishedAgents($: Api): Promise<number> {
  let removed = 0
  const order = await read($, orderAtom)
  let nextOrder = order
  await update($, agentsAtom, (m: Agents) => {
    const c = clearFinished(m, order)
    removed = c.removed
    nextOrder = c.order
    return c.agents
  })
  await update($, orderAtom, () => nextOrder)
  const agents = await read($, agentsAtom)
  await update($, expandedAtom, (x: string[]) => x.filter(id => agents[id] !== undefined))
  return removed
}

async function toggleExpanded($: Api, id: string): Promise<void> {
  await update($, expandedAtom, (x: string[]) => (x.includes(id) ? x.filter(y => y !== id) : [...x, id]))
}

async function setBand($: Api, value: boolean): Promise<void> {
  await update($, bandAtom, () => value)
  try {
    await $.store.set(BAND_KEY, value)
  } catch {
    // Kept for this session only
  }
}

async function mapText($: Api): Promise<string> {
  const agents = await read($, agentsAtom)
  const order = await read($, orderAtom)
  return treeText(agents, order, await nowOf($), undefined, cfg.stuckAfterMs)
}

/** First press arms the row's Stop button; a second press within ARM_MS stops the agent. */
async function pressStop($: Api, id: string): Promise<void> {
  const armed = await read($, armedAtom)
  if (armed === id) {
    armTimer?.cancel()
    armTimer = null
    await update($, armedAtom, () => null)
    await stopAgent($, id)
    return
  }
  await update($, armedAtom, () => id)
  armTimer?.cancel()
  armTimer = $.clock.after(ARM_MS, () => {
    armTimer = null
    void update($, armedAtom, (x: string | null) => (x === id ? null : x)).catch(() => undefined)
  })
}

/**
 * Stops a running agent with Claude Code's own TaskStop, raised with the
 * person's press as consent. When TaskStop can't (a foreground subagent, an
 * id it doesn't know), the agent is muted instead: its next tool calls are
 * refused with a reason that asks it to return its result now.
 */
async function stopAgent($: Api, id: string): Promise<void> {
  const a = (await read($, agentsAtom))[id]
  if (!a || a.status !== 'running') return
  // The consent reads to the engine as the person's words: the type and id, never a model-written description.
  const consent = 'The user pressed "Stop" on the ' + JSON.stringify(cut(a.name || 'agent', 30)) + ' agent ' + cut(id, 60) + ' in the agent map pane'
  ownStops.add(id)
  let r: { deny?: string; isError?: boolean; text?: unknown } | undefined
  try {
    r = (await $.tool.call({ tool: 'TaskStop', task_id: id, consent } as never)) as typeof r
  } catch (err) {
    r = { deny: String(err instanceof Error ? err.message : err) }
  } finally {
    ownStops.delete(id)
  }
  const why = r?.deny || (r?.isError ? String(r.text ?? '').replace(/\s+/g, ' ').trim() || 'the tool reported an error' : '')
  if (!why) {
    const was = (await read($, agentsAtom))[id]?.status
    await changeAgent($, id, (x, now) => markStopped(x, STOPPED_BY_YOU, now))
    // noteStop may have logged it already, from inside the TaskStop call
    if (was === 'running') await logEvent($, id, 'stopped', 'by ' + STOPPED_BY_YOU)
    await syncTicker($)
    return
  }
  await changeAgent($, id, x => markMuted(x))
  await logEvent($, id, 'muted', 'TaskStop refused: ' + cut(why, 60))
  try {
    await $.ui.toast('Could not stop ' + cut(labelOf(a), 40) + ' (' + cut(why, 80) + '). Muted it: its next tool calls are refused.')
  } catch {
    // The row shows ⊘ muted
  }
}

/** A TaskStop that went through: the agent it named is stopped, by whoever called it. */
async function noteStop($: Api, e: unknown, r: unknown, caller: string): Promise<void> {
  const res = (r && typeof r === 'object' ? r : {}) as { deny?: unknown; isError?: unknown }
  if (res.deny || res.isError) return
  const agents = await read($, agentsAtom)
  const target = resolveAddress(agents, str(e, 'task_id', 'shell_id'))
  if (!target || target === MAIN || agents[target]?.status !== 'running') return
  const by = ownStops.has(target) ? STOPPED_BY_YOU : caller === MAIN ? 'main' : labelOf(agents[caller], caller)
  await changeAgent($, target, (x, now) => markStopped(x, by, now))
  await logEvent($, target, 'stopped', 'by ' + by)
}

const USAGE = 'Usage: /agent-map [clear | band on | band off | text | cards | tree | team | view <cards|tree|team> | log | cap <kind> <n> | cap reset [kind]]'

function capsText(c: CapConfig, counters: CapCounters, running: number): string {
  const v = (n: number) => (n > 0 ? String(n) : 'off')
  return (
    'agent-map caps: concurrent ' + v(c.maxConcurrent) + ' (now ' + running + ') · turn ' + v(c.maxPerTurn) + ' (now ' + counters.turn + ') · session ' +
    v(c.maxPerSession) + ' (now ' + counters.session + ') · returned ' + (c.maxReturnedTokens > 0 ? fmtTokens(c.maxReturnedTokens) : 'off') +
    ' (now ' + fmtTokens(counters.returnedTotal) + ') · warn at ' + Math.round(c.warnAt * 100) + '% · waiting grace ' + c.waitGraceMs + ' ms'
  )
}

/** One cap's value as /agent-map cap says it: `90%`, `200k tok`, `1500 ms`, `6`; `off` for 0. */
function shownCap(caps: CapConfig, kind: CapCommandKind): string {
  if (kind === 'warn') return Math.round(caps.warnAt * 100) + '%'
  if (kind === 'grace') return caps.waitGraceMs === 0 ? '0 ms (waits show at once)' : caps.waitGraceMs + ' ms'
  const n = caps[capKeyOf(kind)]
  if (n === 0) return 'off'
  return kind === 'returned' ? fmtTokens(n) + ' tok' : String(n)
}

async function savedCaps($: Api): Promise<Record<string, unknown>> {
  try {
    const s = await $.store.get(CAPS_KEY)
    if (s && typeof s === 'object') return { ...(s as Record<string, unknown>) }
  } catch {
    // Start a fresh override set
  }
  return {}
}

/** `/agent-map cap reset [kind]`: drops that kind's saved override (every one without a kind) and loads the caps again. */
async function resetCap($: Api, args: string[]): Promise<string> {
  const r = parseCapReset(args)
  if ('error' in r) return r.error
  let saved = await savedCaps($)
  if (r.key) delete saved[r.key]
  else saved = {}
  try {
    await $.store.set(CAPS_KEY, saved)
  } catch {
    // Nothing saved to clear
  }
  await loadCaps($).catch(() => undefined)
  const caps = await read($, capsAtom)
  if (!r.kind || !r.key) return 'agent-map: saved caps cleared. ' + capsText(caps, await read($, countersAtom), runningCount(await read($, agentsAtom)))
  return 'agent-map: ' + r.kind + ' cap reset to ' + shownCap(caps, r.kind) + ' (' + (await read($, capSourcesAtom))[r.key] + ')'
}

async function setCap($: Api, args: string[]): Promise<string> {
  if (args.length === 0) return capsText(await read($, capsAtom), await read($, countersAtom), runningCount(await read($, agentsAtom)))
  if (args[0] === 'reset') return resetCap($, args)
  const cmd = parseCapCommand(args)
  if ('error' in cmd) return cmd.error
  const key = capKeyOf(cmd.kind)
  const saved = await savedCaps($)
  saved[key] = cmd.value
  try {
    await $.store.set(CAPS_KEY, saved)
  } catch {
    // Kept for this session only
  }
  await update($, capsAtom, (c: CapConfig) => mergeCaps(c, { [key]: cmd.value }))
  await update($, capSourcesAtom, (s: CapSources) => ({ ...s, [key]: 'saved (/agent-map cap)' }))
  return 'agent-map: ' + cmd.kind + ' cap set to ' + shownCap(await read($, capsAtom), cmd.kind)
}

async function viewText($: Api, view: PaneView): Promise<string> {
  const agents = await read($, agentsAtom)
  const order = await read($, orderAtom)
  const now = await nowOf($)
  if (view === 'cards') return cardsText(agents, order, now, undefined, cfg.stuckAfterMs)
  if (view === 'team') return teamText(agents, order, now, undefined, cfg.stuckAfterMs)
  return treeText(agents, order, now, undefined, cfg.stuckAfterMs)
}

export const register: Register = (on, options) => {
  cfg = parseConfig(options)
  regOptions = options

  on('session.start', async ($, e, next) => {
    sessionCwd = str(e, 'cwd') ?? sessionCwd
    await loadBand($)
    await loadCaps($).catch(() => undefined)
    await loadView($)
    await loadWindow($)
    await syncTicker($)
    try {
      await $.command.register({
        name: COMMAND,
        description: 'Open the agent deck: cards with cost, tokens, context and progress, the tree or team view, the lifecycle log, and spawn caps',
        argumentHint: '[cards | tree | team | log | text | clear | band on|off | cap <kind> <n> | cap reset [kind]]',
        immediate: true,
      })
    } catch {
      // The name is taken: the map still draws, without the command
    }
    return next(e)
  })

  // /clear, /resume and /branch reset $.state: load the band switch again
  on('classic.SessionStart', { source: ['clear', 'resume', 'fork'] }, async ($, e, next) => {
    if (ticker) {
      ticker.cancel()
      ticker = null
    }
    armTimer?.cancel()
    armTimer = null
    peekedAt.clear()
    callLoop.clear()
    for (const k of Array.from(pendingAsks.keys())) cancelAsk(k)
    inflight.clear()
    spawnNotes.clear()
    agentOfCall.clear()
    returnedOfCall.clear()
    await loadBand($)
    await loadCaps($).catch(() => undefined)
    await loadView($)
    await loadWindow($)
    return next(e)
  })

  // A cap setting changed in /config: an out-of-range value is refused before it is written, and
  // the caps load again once it is. A guard that fails refuses rather than letting the value through.
  on('config.set', { key: SETTING_KEY }, async ($, e, next) => {
    const field = SETTING_KEY.exec(e.key)?.[2]
    const problem = field ? settingProblem(field, e.value) : undefined
    if (problem) return { deny: problem }
    const r = await next(e)
    await loadCaps($).catch(() => undefined)
    return r
  }).catch(($, e, next) => (next.called ? next(e) : { deny: 'agent-map could not check this value' }))

  // A settings file changed outside /config (the desktop's plugin settings may write it directly)
  on('classic.ConfigChange', async ($, e, next) => {
    const r = await next(e)
    await loadCaps($).catch(() => undefined)
    return r
  })

  on('tool.call', async ($, e, next) => {
    const id = str(e, 'agentId') ?? MAIN
    const tool = str(e, 'tool') ?? 'tool'
    const toolUseId = str(e, 'tool_use_id')
    try {
      // The mute: TaskStop couldn't stop this agent, so its tool calls end here
      if (id !== MAIN) {
        const a = (await read($, agentsAtom))[id]
        if (a?.muted && a.status === 'running') return { deny: MUTE_REASON }
      }
    } catch {
      // No map to read: let the call through
    }
    try {
      if (toolUseId) callLoop.set(toolUseId, id)
      const own = tool === 'TaskStop' && id === MAIN && ownStops.has(str(e, 'task_id') ?? '')
      if (!own) {
        if (tool === 'Agent' || tool === 'Task') {
          const now = await nowOf($)
          await update($, pendingAtom, (l: PendingCall[]) => addPending(l, pendingOf(e, now)))
        }
        const before = id === MAIN ? undefined : (await read($, agentsAtom))[id]
        const activity = activityOf(tool, e)
        // TodoWrite's list is the agent's progress: completed / all, and the item in progress
        const todo = tool === 'TodoWrite' ? todoOf(e) : undefined
        await changeAgent($, id, (a, now) => {
          const x = applyToolCall(a, tool, activity, now)
          return todo === undefined ? x : { ...x, todo }
        })
        if (before?.isSpawned && before.toolCalls === 0) await logEvent($, id, 'first-tool', activity)
      }
    } catch {
      // Observing only: never stand in the tool's way
    }
    let r: unknown
    try {
      r = await next(e)
      return r as Awaited<ReturnType<typeof next>>
    } finally {
      try {
        if (toolUseId) {
          callLoop.delete(toolUseId)
          // An ask the call outran (auto-approved within the grace) never shows
          cancelAsk(toolUseId)
          // The call ran (or was refused): it no longer waits on the person.
          // clearWaiting hands back the same map when nothing waited, so no redraw then.
          let waited: string[] = []
          await update($, agentsAtom, (m: Agents) => {
            waited = Object.values(m).filter(a => a.waiting?.some(w => w.toolUseId === toolUseId)).map(a => a.id)
            return clearWaiting(m, toolUseId)
          })
          for (const w of waited) await logEvent($, w, 'resumed', 'after ' + tool)
        }
        if ((tool === 'Agent' || tool === 'Task') && toolUseId && r) {
          const res = r as { deny?: unknown; isError?: unknown }
          // A refused call never spawns: it leaves the planned list
          if (res.deny || res.isError) await dropPending($, toolUseId)
          await noteReturned($, toolUseId, id, estimateTokens(resultText(r)))
        }
        if (tool === 'TaskStop') await noteStop($, e, r, id)
      } catch {
        // Best effort
      }
    }
  })

  // Permission verdicts: a call put to the person shows ⏸ waiting on its loop's row until it runs
  on('tool.check', async ($, e, next) => {
    try {
      const toolUseId = str(e, 'tool_use_id')
      const verdict = toolUseId ? await $.tool.check({ tool: e.tool, input: e.input }) : null
      if (toolUseId && verdict && verdict.decision === 'ask') {
        const id = callLoop.get(toolUseId) ?? str(e, 'agentId') ?? MAIN
        const tool = str(e, 'tool') ?? 'tool'
        const grace = (await read($, capsAtom)).waitGraceMs
        cancelAsk(toolUseId)
        pendingAsks.set(toolUseId, { loop: id, tool, timer: null })
        if (grace <= 0) await markWaiting($, toolUseId)
        else armGrace($, toolUseId, grace)
      }
    } catch {
      // Observing only
    }
    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    const o = e as unknown as Record<string, unknown>
    const key = str(o, 'tool_use_id') ?? 'spawn:' + ++spawnSeq
    let refusal: string | null = null
    try {
      refusal = await serialized(() => gate($, o, key))
    } catch {
      // A gate that fails lets the spawn through
      refusal = null
    }
    if (refusal) {
      await dropPending($, str(o, 'tool_use_id')).catch(() => undefined)
      return { deny: refusal }
    }
    // The override marker is for the gate: the subagent gets its task without it
    let input = e
    if (overrideReason(o.description, o.prompt)) {
      input = { ...e, description: stripOverride(String(o.description ?? '')), prompt: stripOverride(String(o.prompt ?? '')) }
    }
    let r: Awaited<ReturnType<typeof next>> | undefined
    let threw = true
    try {
      r = await next(input)
      threw = false
      return r
    } finally {
      try {
        if (r && typeof r === 'object' && (r as { deny?: unknown }).deny) {
          await ungate($, key, o)
          await dropPending($, str(o, 'tool_use_id'))
        }
        // A spawn that throws still draws, as failed
        else await recordSpawn($, input, r, threw, key)
      } catch {
        // The spawn stands whatever the map does
      } finally {
        inflight.delete(key)
      }
    }
  })

  // A permission dialog is on screen: the matching pending ask shows ⏸ waiting at once
  on('classic.PermissionRequest', async ($, e, next) => {
    try {
      dialogSignal = true
      const loop = str(e, 'agent_id', 'agentId') ?? MAIN
      const tool = str(e, 'tool_name', 'tool')
      for (const [k, p] of pendingAsks) {
        if (p.loop === loop && (!tool || p.tool === tool)) {
          await markWaiting($, k)
          break
        }
      }
    } catch {
      // Observing only
    }
    return next(e)
  })

  // The settings PreToolUse point: a call that reaches it is going to run, so a
  // pending ask for it is dropped and a shown ⏸ waiting clears
  on('classic.PreToolUse', async ($, e, next) => {
    try {
      await clearApprovedWait($, e)
    } catch {
      // Observing only
    }
    return next(e)
  })

  // A new main-loop turn: the per-turn count, the warning and the override start over
  on('turn.start', async ($, e, next) => {
    try {
      if (!str(e, 'agentId')) await update($, countersAtom, (c: CapCounters) => newTurn(c))
    } catch {
      // Best effort
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    try {
      const id = str(e, 'agentId') ?? MAIN
      const usage = result && typeof result === 'object' ? (result as { usage?: unknown }).usage : undefined
      const known = id === MAIN || (await read($, agentsAtom))[id]?.isSpawned === true
      // e.effort is the request's effort as this hook received it (a mod above may have rewritten it)
      const step = { effort: effortOf((e as unknown as { effort?: unknown }).effort), prices: await read($, pricesAtom) }
      await changeAgent($, id, (a, now) => applyStep(resume(a, now), usage, str(e, 'model'), now, step))
      if (id !== MAIN) {
        // A loop no spawn announced: the engine's list may name it (a fork, a teammate)
        if (!known) await reconcileList($)
        await syncTicker($)
      }
    } catch {
      // Counting is best effort
    }
    return result
  })

  on('turn.complete', async ($, e, next) => {
    try {
      await recordComplete($, e, false)
    } catch {
      // Best effort
    }
    return next(e)
  }).catch(async ($, e, next) => {
    try {
      await recordComplete($, e, true)
    } catch {
      // Best effort
    }
    return next.called ? { text: '' } : next(e)
  })

  on('session.send', async ($, e, next) => {
    try {
      const o = e as unknown as Record<string, unknown>
      await recordMessage($, str(o, 'agentId', 'from') ?? MAIN, o.to)
    } catch {
      // Best effort
    }
    return next(e)
  })

  on('session.receive', async ($, e, next) => {
    try {
      const o = e as unknown as Record<string, unknown>
      const origin = (o.origin && typeof o.origin === 'object' ? o.origin : {}) as Record<string, unknown>
      if (origin.kind === 'task-notification') {
        // A background agent's result reaches main as a task notification
        const task = (o.task && typeof o.task === 'object' ? o.task : origin.task && typeof origin.task === 'object' ? origin.task : {}) as Record<string, unknown>
        const agents = await read($, agentsAtom)
        const viaCall = str(task, 'toolUseId') ?? str(origin, 'toolUseId', 'tool_use_id')
        const id = resolveAddress(agents, str(task, 'id') ?? str(origin, 'agentId', 'taskId', 'id')) ?? (viaCall ? agentOfCall.get(viaCall) : undefined)
        const tokens = estimateTokens(typeof o.text === 'string' ? o.text : '')
        if (id && id !== MAIN && tokens > 0) {
          await changeAgent($, id, a => addReturned(a, tokens))
          await logEvent($, id, 'returned', fmtTokens(tokens) + ' tok to main (task notification)')
          await addToMain($, tokens)
        }
      } else {
        const from = str(o, 'from', 'agentId', 'sender') ?? str(origin, 'agentId', 'from', 'name')
        if (from) await recordMessage($, from, str(o, 'to') ?? MAIN)
      }
    } catch {
      // Best effort
    }
    return next(e)
  })

  on('command.run', { command: 'agent-map' }, async ($, e) => {
    const args = (str(e, 'args') ?? '').trim().toLowerCase().split(/\s+/).filter(Boolean)
    const verb = args[0] ?? ''
    await reconcileList($).catch(() => undefined)
    if (verb === '' || verb === 'open') {
      try {
        await $.ui.open({ id: PANE, title: TITLE, focus: true, closeOnEscape: true })
      } catch {
        return { text: await mapText($) }
      }
      return {}
    }
    if (verb === 'clear') {
      const n = await clearFinishedAgents($)
      return { text: 'Cleared ' + n + ' finished agent' + (n === 1 ? '' : 's') }
    }
    if (verb === 'band') {
      const want = args[1]
      if (want !== 'on' && want !== 'off') return { text: USAGE }
      await setBand($, want === 'on')
      return { text: 'Agent band ' + want }
    }
    // Text prints the chosen view; with none chosen, the tree (the pane opens on the cards)
    if (verb === 'text') return { text: await viewText($, (await read($, viewAtom)) ?? 'tree') }
    const chosen = verb === 'view' ? (args[1] ?? '') : verb
    if (chosen === 'tree' || chosen === 'cards' || chosen === 'team') {
      const verb = chosen
      await setView($, verb)
      try {
        await $.ui.open({ id: PANE, title: TITLE, focus: true, closeOnEscape: true })
      } catch {
        return { text: await viewText($, verb) }
      }
      return { text: 'Agent map: ' + verb + ' view' }
    }
    if (verb === 'log') return { text: logText(await read($, logAtom)) }
    if (verb === 'cap') return { text: await setCap($, args.slice(1)) }
    return { text: USAGE }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const props = (e.props ?? {}) as { hasSurvey?: boolean; bodyColumns?: number }
    if (props.hasSurvey) return next(e)
    if (!(await read($, everAtom)) || !(await read($, bandAtom))) return next(e)
    const counters = await read($, countersAtom)
    const band = bandOf(await read($, agentsAtom), { caps: await read($, capsAtom), counters })
    const { Box, Text } = $.ui.resolve(e)
    const k = makeKit($.ui.resolve(e) as unknown as Elements, e.surface)
    // One kit line: `agents  ● 3/4 running  ✓ 5 done  ✗ 1  ● ok` with the tokens on the right
    const chips = band.chips.map(c => k.text(c.text, { color: TONES[c.tone].fg, bold: c.tone !== 'muted', wrap: 'truncate' }))
    const mine = Box({
      key: 'agent-map-band',
      flexDirection: 'column',
      children: [k.line('agents', chips, band.right) as ReturnType<typeof Text>],
    })
    const theirs = await next(e)
    if (theirs && typeof theirs === 'object') return Box({ flexDirection: 'column', children: [mine, theirs] })
    return mine
  })

  on('ui.render', { component: 'Pane', requestId: 'agent-map' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const k = makeKit(ui as unknown as Elements, e.surface)
    const props = (e.props ?? {}) as { bodyColumns?: number }
    const columns = Math.max(20, props.bodyColumns ?? 80)
    const agents = await read($, agentsAtom)
    const order = await read($, orderAtom)
    const expanded = await read($, expandedAtom)
    const now = await read($, nowAtom)
    const armed = await read($, armedAtom)
    const view: PaneView = (await read($, viewAtom)) ?? 'cards'
    const showLog = await read($, showLogAtom)
    const collapsed = await read($, collapsedAtom)
    const treeOpts = { now, columns, expanded, stuckAfterMs: cfg.stuckAfterMs, reserve: STOP_RESERVE }
    const handlers = {
      toggle: (id: string) => toggleExpanded($, id),
      stop: (id: string) => pressStop($, id),
      collapse: () => update($, collapsedAtom, (x: boolean) => !x),
      view: (v: PaneView) => setView($, v),
    }

    const stopButton = (id: string) =>
      Button({
        key: 'stop-' + id,
        label: armed === id ? 'Confirm stop' : 'Stop',
        plain: true,
        onPress: () => pressStop($, id),
      })

    const rowOf = (r: Row, i: number) => {
      const parts = []
      if (r.prefix) parts.push(Text({ color: 'inactive', children: [r.prefix] }))
      if (r.kind === 'agent' && r.id) {
        const id = r.id
        parts.push(Text({ color: r.color ?? 'inactive', children: [(r.glyph ?? '') + ' '] }))
        parts.push(
          Button({
            key: 'row-' + id,
            label: r.body,
            plain: true,
            onPress: () => toggleExpanded($, id),
          }),
        )
        if (r.flag) parts.push(Text({ color: r.flagColor ?? 'inactive', wrap: 'truncate-end', children: [r.flag] }))
        if (r.canStop) {
          parts.push(Text({ children: ['  '] }))
          parts.push(stopButton(id))
        }
      } else if (r.kind === 'header' || r.kind === 'lane') {
        parts.push(Text({ bold: true, wrap: 'truncate-end', children: [r.body] }))
      } else {
        parts.push(Text({ color: 'inactive', wrap: 'truncate-end', children: [r.body] }))
      }
      return Box({ key: 'line-' + i, flexDirection: 'row', children: parts })
    }

    // The page: the header block (tiles, buttons and, in the cards view, the main loop's line), the
    // view's body, the caps, the log, the footer buttons, one row apart. Rows inside a block stay tight; the
    // tree views keep the main line on top of their tree.
    let head: unknown
    let body: unknown
    if (view === 'cards') {
      head = headerTree(k, agents, now, { view, collapsed, on: handlers, main: mainRow(k, agents, ui as unknown as Elements) })
      body = cardsTree(k, agents, order, now, {
        ui: ui as unknown as Elements,
        columns,
        window: await read($, windowAtom),
        pending: await read($, pendingAtom),
        expanded,
        collapsed,
        armed,
        stuckAfterMs: cfg.stuckAfterMs,
        on: handlers,
      })
    } else {
      head = headerTree(k, agents, now, { view, collapsed, on: handlers })
      const rows = buildRows(agents, order, treeOpts)
      if (view === 'team') {
        // One tight stack per top-level lane (team of main, teammates, unattached), one row apart; the
        // main line leads the first, and nested lanes stay in their top-level lane's stack
        const lanes: unknown[][] = [[rowOf(rows[0], 0)]]
        teamRows(agents, order, treeOpts).forEach((r, i) => {
          if (i > 0 && r.kind === 'lane' && !r.prefix) lanes.push([])
          lanes[lanes.length - 1].push(rowOf(r, i + 1))
        })
        body = k.list(lanes.map(l => k.stack(l)))
      } else body = k.stack(rows.map(rowOf))
    }
    const log = showLog ? k.stack(logRows(await read($, logAtom), columns).map((r, i) => rowOf(r, 10_000 + i))) : null
    const caps = capsTree(k, await read($, capsAtom), await read($, capSourcesAtom))

    return k.page([
      head,
      body,
      caps,
      log,
      k.buttons([
        { key: 'clear', label: 'Clear finished', onPress: () => clearFinishedAgents($) },
        { key: 'log', label: showLog ? 'Hide log' : 'Log', onPress: () => update($, showLogAtom, (x: boolean) => !x) },
        { key: 'close', label: 'Close', onPress: () => $.ui.close({ id: PANE }) },
      ]),
    ]) as never
  })
}

files.hooks/model.ts:
// Pure data functions for agent-map. Nothing here touches `$`: register.ts
// reads and writes $.state and hands these functions plain values.
import type { AgentRecord, AgentStatus, CapConfig, CapCounters, CapKind, CapSource, CapSources, LogEntry, PendingCall, PriceRow, TodoProgress, TokenCounts, WaitingCall } from '../types'
import { costUsd } from './prices'

export const MAIN = 'main'
export const MAX_PENDING = 32
export const MAX_MESSAGES = 20
export const ACTIVITY_INPUT = 40
export const MAX_WAITING = 8

export type Agents = Record<string, AgentRecord>

/** Reads a string field from an event, trying each name in turn. */
export function str(e: unknown, ...names: string[]): string | undefined {
  if (!e || typeof e !== 'object') return undefined
  const o = e as Record<string, unknown>
  for (const n of names) {
    const v = o[n]
    if (typeof v === 'string' && v.length > 0) return v
  }
  return undefined
}

export function num(v: unknown): number {
  return typeof v === 'number' && Number.isFinite(v) ? v : 0
}

export function zeroTokens(): TokenCounts {
  return { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 }
}

export function totalTokens(t: TokenCounts | undefined): number {
  if (!t) return 0
  return num(t.input) + num(t.output) + num(t.cacheRead) + num(t.cacheCreate)
}

/** Token counts from an API usage object (turn.step result.usage, turn.complete e.usage). */
export function tokensOf(usage: unknown): TokenCounts {
  const u = (usage && typeof usage === 'object' ? usage : {}) as Record<string, unknown>
  return {
    input: num(u.input_tokens),
    output: num(u.output_tokens),
    cacheRead: num(u.cache_read_input_tokens),
    cacheCreate: num(u.cache_creation_input_tokens),
  }
}

export function addTokens(a: TokenCounts, b: TokenCounts): TokenCounts {
  return {
    input: num(a.input) + b.input,
    output: num(a.output) + b.output,
    cacheRead: num(a.cacheRead) + b.cacheRead,
    cacheCreate: num(a.cacheCreate) + b.cacheCreate,
  }
}

export function blankAgent(id: string, now: number): AgentRecord {
  const isMain = id === MAIN
  return {
    id,
    name: isMain ? 'orchestrator' : 'agent',
    description: isMain ? 'main' : '',
    prompt: '',
    model: '',
    parent: isMain ? '' : MAIN,
    isTeammate: false,
    isFork: false,
    isBackground: false,
    isSpawned: isMain,
    startedAt: now,
    runStartedAt: now,
    status: 'running',
    requests: 0,
    toolCalls: 0,
    toolsByName: {},
    lastTool: '',
    activity: '',
    lastActiveAt: now,
    waiting: [],
    stuckNotified: false,
    muted: false,
    tokens: zeroTokens(),
    messages: [],
    effort: '',
    lastRequestTokens: 0,
    todo: null,
    costUsd: null,
  }
}

/** Returns a copy of `agents` with `id` changed by `fn`, creating the record when missing. */
export function withAgent(agents: Agents, id: string, now: number, fn: (a: AgentRecord) => AgentRecord): Agents {
  const prev = agents[id] ?? blankAgent(id, now)
  return { ...agents, [id]: fn(prev) }
}

export function withOrder(order: string[], id: string): string[] {
  return order.includes(id) ? order : [...order, id]
}

// ---- Agent tool calls and spawns ----

/** What a model's Agent tool.call says about the agent about to start. */
export function pendingOf(e: unknown, now: number): PendingCall {
  const o = (e && typeof e === 'object' ? e : {}) as Record<string, unknown>
  return {
    toolUseId: str(o, 'tool_use_id', 'toolUseId') ?? '',
    caller: str(o, 'agentId') ?? MAIN,
    description: str(o, 'description') ?? '',
    subagentType: str(o, 'subagent_type', 'subagentType') ?? '',
    model: str(o, 'model') ?? '',
    prompt: str(o, 'prompt') ?? '',
    isBackground: o.run_in_background === true,
    at: now,
  }
}

export function addPending(list: PendingCall[], p: PendingCall): PendingCall[] {
  return [...list, p].slice(-MAX_PENDING)
}

/**
 * Finds the Agent call a spawn belongs to: by tool_use_id, then by
 * description, then the oldest still waiting. Returns it and the rest.
 */
export function takePending(list: PendingCall[], spawn: unknown): { match?: PendingCall; rest: PendingCall[] } {
  const toolUseId = str(spawn, 'tool_use_id', 'toolUseId')
  const description = str(spawn, 'description')
  let i = toolUseId ? list.findIndex(p => p.toolUseId === toolUseId) : -1
  if (i < 0 && description) i = list.findIndex(p => p.description === description)
  if (i < 0 && !toolUseId && list.length > 0) i = 0
  if (i < 0) return { rest: list }
  return { match: list[i], rest: list.filter((_, j) => j !== i) }
}

export type SpawnFacts = {
  id: string
  parent: string
  name: string
  description: string
  prompt: string
  model: string
  isTeammate: boolean
  isFork: boolean
  isBackground: boolean
  /** The spawn's effort, when the event carries one (not a documented field: read defensively). */
  effort: string
}

/**
 * Merges what agent.spawn's input (e), its result (r) and the matching Agent
 * tool.call (p) say. The caller of the Agent tool is the parent.
 */
export function spawnFacts(e: unknown, r: unknown, p: PendingCall | undefined): SpawnFacts {
  const o = (e && typeof e === 'object' ? e : {}) as Record<string, unknown>
  const toolUseId = str(o, 'tool_use_id', 'toolUseId')
  const id =
    str(r, 'agentId') ??
    str(o, 'agentId', 'id') ??
    (toolUseId ? 'tool:' + toolUseId : 'agent:' + (str(o, 'description') ?? 'unknown'))
  return {
    id,
    parent: str(o, 'parentAgentId') ?? p?.caller ?? MAIN,
    name:
      str(o, 'subagentType', 'subagent_type', 'agentType', 'type') ??
      (p?.subagentType || undefined) ??
      (o.isTeammate === true ? 'teammate' : 'general-purpose'),
    description: str(o, 'description', 'name') ?? p?.description ?? '',
    prompt: str(o, 'prompt') ?? p?.prompt ?? '',
    model: str(r, 'model') ?? str(o, 'model') ?? (p?.model || undefined) ?? str(o, 'parentModel') ?? '',
    isTeammate: o.isTeammate === true,
    isFork: o.fork === true,
    isBackground: o.background === true || o.run_in_background === true || p?.isBackground === true,
    effort: effortOf(o.effort),
  }
}

export function applySpawn(a: AgentRecord, f: SpawnFacts, now: number): AgentRecord {
  return {
    ...a,
    name: f.name || a.name,
    description: f.description || a.description,
    prompt: f.prompt || a.prompt,
    model: f.model || a.model,
    parent: f.parent === f.id ? MAIN : f.parent,
    isTeammate: f.isTeammate || a.isTeammate,
    isFork: f.isFork || a.isFork,
    isBackground: f.isBackground,
    // A request's effort (turn.step) stands over the spawn's
    effort: a.effort || f.effort || '',
    isSpawned: true,
    // Keep the earlier start when a tool call or step arrived before the spawn resolved
    startedAt: a.isSpawned || a.requests > 0 || a.toolCalls > 0 ? a.startedAt : now,
    runStartedAt: a.isSpawned || a.requests > 0 || a.toolCalls > 0 ? a.runStartedAt : now,
    status: 'running',
    endedAt: undefined,
    lastActiveAt: now,
  }
}

// ---- Activity inside a loop ----

const INPUT_KEYS = ['command', 'file_path', 'pattern', 'description', 'url', 'query', 'path', 'skill', 'task_id', 'prompt']

const oneLine = (s: string) => s.replace(/\s+/g, ' ').trim()

/** `Bash: npm test`: the tool and the first 40 characters of the input that says most about the call. */
export function activityOf(tool: string, e: unknown): string {
  const name = tool || 'tool'
  const o = (e && typeof e === 'object' ? e : {}) as Record<string, unknown>
  const input = (o.input && typeof o.input === 'object' ? o.input : o) as Record<string, unknown>
  const raw = str(input, ...INPUT_KEYS)
  const text = raw ? Array.from(oneLine(raw)).slice(0, ACTIVITY_INPUT).join('') : ''
  return text ? name + ': ' + text : name
}

export function applyToolCall(a: AgentRecord, tool: string, activity?: string, now?: number): AgentRecord {
  const name = tool || 'tool'
  return {
    ...a,
    toolCalls: a.toolCalls + 1,
    toolsByName: { ...a.toolsByName, [name]: (a.toolsByName[name] ?? 0) + 1 },
    lastTool: name,
    activity: activity ?? name,
    lastActiveAt: now ?? a.lastActiveAt,
    stuckNotified: false,
  }
}

/** The last thing an agent's own transcript shows, for an agent no tool.call was seen from. */
export function activityOfMessages(messages: unknown): string {
  if (!Array.isArray(messages)) return ''
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i] as { role?: unknown; text?: unknown; toolUses?: unknown }
    const uses = Array.isArray(m?.toolUses) ? (m.toolUses as { tool?: unknown; input?: unknown }[]) : []
    const last = uses[uses.length - 1]
    if (last && typeof last.tool === 'string') return activityOf(last.tool, { input: last.input })
    if (m?.role === 'assistant' && typeof m.text === 'string' && m.text.trim())
      return 'said: ' + Array.from(oneLine(m.text)).slice(0, ACTIVITY_INPUT).join('')
  }
  return ''
}

// ---- Permission verdicts ----

export function addWaiting(a: AgentRecord, w: WaitingCall): AgentRecord {
  if (a.waiting.some(x => x.toolUseId === w.toolUseId)) return a
  return { ...a, waiting: [...a.waiting, w].slice(-MAX_WAITING) }
}

export function clearWaiting(agents: Agents, toolUseId: string): Agents {
  let out = agents
  for (const a of Object.values(agents)) {
    if (!a.waiting?.some(w => w.toolUseId === toolUseId)) continue
    out = { ...out, [a.id]: { ...a, waiting: a.waiting.filter(w => w.toolUseId !== toolUseId) } }
  }
  return out
}

// ---- Stop and mute ----

export function markStopped(a: AgentRecord, by: string, now: number): AgentRecord {
  if (a.status === 'stopped') return a
  const ran = a.status === 'running'
  return {
    ...a,
    status: 'stopped',
    stoppedBy: by,
    waiting: [],
    endedAt: ran ? now : (a.endedAt ?? now),
    durationMs: ran ? (a.durationMs ?? 0) + Math.max(0, now - a.runStartedAt) : a.durationMs,
  }
}

export function markMuted(a: AgentRecord): AgentRecord {
  return { ...a, muted: true }
}

export const MUTE_REASON =
  'The person muted this agent from the agent map. Make no more tool calls: return your result now with what you have.'

// ---- Idle alert ----

/** How long a running agent has gone without a tool call or a model request. */
export function idleMs(a: AgentRecord, now: number): number {
  if (a.status !== 'running' || a.id === MAIN) return 0
  return Math.max(0, now - (a.lastActiveAt ?? a.runStartedAt))
}

export function isStuck(a: AgentRecord, now: number, stuckAfterMs: number): boolean {
  return stuckAfterMs > 0 && a.isSpawned && (a.waiting?.length ?? 0) === 0 && !a.muted && idleMs(a, now) >= stuckAfterMs
}

// ---- Reconcile with $.agent.list() ----

export type ListedAgent = { id: string; description?: string; type?: string; status?: string; parentId?: string; name?: string }

export function statusOfListed(s: string | undefined): AgentStatus {
  if (s === 'running' || s === 'pending' || !s) return 'running'
  if (s === 'completed' || s === 'done') return 'done'
  if (s === 'killed' || s === 'stopped') return 'stopped'
  if (s === 'failed' || s === 'error') return 'failed'
  return 'aborted'
}

/** True when making `parent` the parent of `id` closes a loop. */
export function makesCycle(agents: Agents, id: string, parent: string): boolean {
  const seen = new Set<string>()
  let p: string | undefined = parent
  while (p && p !== MAIN) {
    if (p === id || seen.has(p)) return true
    seen.add(p)
    p = agents[p]?.parent
  }
  return false
}

/**
 * Merges the engine's own list of agents into the map: agents the spawn hook
 * missed (forks, teammates, workflow agents, ones that started before a
 * reload) appear, parents fill in, and finished ones end. A parent that would
 * close a loop is left at main.
 */
export function reconcile(agents: Agents, order: string[], listed: readonly ListedAgent[], now: number): { agents: Agents; order: string[]; added: string[] } {
  let out = agents
  let nextOrder = order
  const added: string[] = []
  for (const l of listed) {
    if (!l || typeof l.id !== 'string' || !l.id || l.id === MAIN) continue
    const status = statusOfListed(l.status)
    const prev = out[l.id]
    const parentId = l.parentId && l.parentId !== l.id ? l.parentId : MAIN
    if (!prev || !prev.isSpawned) {
      const base = prev ?? blankAgent(l.id, now)
      const parent = makesCycle(out, l.id, parentId) ? MAIN : parentId
      let rec: AgentRecord = {
        ...base,
        name: l.type || base.name,
        description: l.description || l.name || base.description,
        parent,
        isTeammate: l.type === 'teammate' || base.isTeammate,
        isSpawned: true,
      }
      if (status !== 'running') rec = status === 'stopped' ? markStopped(rec, 'engine', now) : { ...rec, status, endedAt: now, durationMs: Math.max(0, now - rec.runStartedAt) }
      out = { ...out, [l.id]: rec }
      nextOrder = withOrder(nextOrder, l.id)
      added.push(l.id)
      continue
    }
    let rec = prev
    if ((rec.parent === MAIN || !rec.parent) && parentId !== MAIN && !makesCycle(out, l.id, parentId)) rec = { ...rec, parent: parentId }
    if (rec.status === 'running' && status !== 'running') {
      rec = status === 'stopped' ? markStopped(rec, rec.stoppedBy ?? 'engine', now) : { ...rec, status, endedAt: now, waiting: [], durationMs: (rec.durationMs ?? 0) + Math.max(0, now - rec.runStartedAt) }
    }
    if (rec !== prev) out = { ...out, [l.id]: rec }
  }
  return { agents: out, order: nextOrder, added }
}

/** A finished agent that makes a request again (a resumed run) is running again. */
export function resume(a: AgentRecord, now: number): AgentRecord {
  if (a.status === 'running' || a.id === MAIN) return a
  return { ...a, status: 'running', endedAt: undefined, runStartedAt: now }
}

export type StepOptions = {
  /** turn.step's e.effort, as effortOf() reads it. */
  effort?: string
  /** The price table the request's cost is figured with (hooks/prices.ts PRICES and the config's overrides). */
  prices?: readonly PriceRow[]
}

/**
 * One model request: tokens and cost add up, the model it actually ran on replaces the spawn's,
 * its effort replaces the spawn's, and its input side (input + cache read + cache write) is
 * kept as the agent's latest context size.
 */
export function applyStep(a: AgentRecord, usage: unknown, model: string | undefined, now?: number, opts: StepOptions = {}): AgentRecord {
  const u = usage && typeof usage === 'object' ? (usage as Record<string, unknown>) : undefined
  const answered = u && typeof u.model === 'string' && u.model ? (u.model as string) : undefined
  const ranOn = answered ?? (model || a.model || '')
  const t = u ? tokensOf(u) : undefined
  const cost = t ? costUsd(t, ranOn, opts.prices) : null
  return {
    ...a,
    requests: a.requests + 1,
    tokens: t ? addTokens(a.tokens, t) : a.tokens,
    model: ranOn,
    lastActiveAt: now ?? a.lastActiveAt,
    stuckNotified: false,
    effort: opts.effort || a.effort || '',
    lastRequestTokens: t ? t.input + t.cacheRead + t.cacheCreate : (a.lastRequestTokens ?? 0),
    costUsd: cost === null ? (a.costUsd ?? null) : (a.costUsd ?? 0) + cost,
  }
}

/** An effort as the card shows it: a level (`low` … `max`) as given, an integer budget as digits, else ''. */
export function effortOf(v: unknown): string {
  if (typeof v === 'number' && Number.isFinite(v) && v > 0) return String(Math.round(v))
  if (typeof v === 'string') return Array.from(oneLine(v)).slice(0, 12).join('')
  return ''
}

/**
 * The progress a TodoWrite call's list shows: completed items over all items, and the
 * in_progress item's activeForm (else its content). Reads `todos` on the event or its `input`.
 * undefined when the call carries no list; null for an empty list.
 */
export function todoOf(e: unknown): TodoProgress | null | undefined {
  const o = (e && typeof e === 'object' ? e : {}) as Record<string, unknown>
  const input = (o.input && typeof o.input === 'object' ? o.input : {}) as Record<string, unknown>
  const list = Array.isArray(o.todos) ? o.todos : Array.isArray(input.todos) ? input.todos : undefined
  if (!list) return undefined
  const items = list.filter(x => x && typeof x === 'object') as Record<string, unknown>[]
  if (items.length === 0) return null
  let done = 0
  let current = ''
  for (const it of items) {
    if (it.status === 'completed') done++
    else if (it.status === 'in_progress' && !current) current = oneLine(str(it, 'activeForm') ?? str(it, 'content') ?? '')
  }
  return { done, total: items.length, current: Array.from(current).slice(0, 80).join('') }
}

export function statusOfComplete(e: unknown): AgentStatus {
  const o = (e && typeof e === 'object' ? e : {}) as Record<string, unknown>
  if (o.isAborted === true || o.reason === 'aborted') return 'aborted'
  if (o.reason === 'error' || o.reason === 'refusal') return 'failed'
  return 'done'
}

export function applyComplete(a: AgentRecord, e: unknown, now: number, status: AgentStatus, prices?: readonly PriceRow[]): AgentRecord {
  const o = (e && typeof e === 'object' ? e : {}) as Record<string, unknown>
  const runMs = typeof o.durationMs === 'number' && o.durationMs >= 0 ? o.durationMs : Math.max(0, now - a.runStartedAt)
  // turn.step already summed this run's tokens; use the turn's totals only when no step was seen
  const fromTurn = a.requests === 0 && o.usage ? tokensOf(o.usage) : undefined
  const tokens = fromTurn ? addTokens(a.tokens, fromTurn) : a.tokens
  const model = a.model || str(o.usage, 'model') || ''
  const turnCost = fromTurn ? costUsd(fromTurn, model, prices) : null
  if (turnCost !== null) a = { ...a, costUsd: (a.costUsd ?? 0) + turnCost }
  if (a.status !== 'running') {
    // A second turn.complete for a finished run (or a .catch after a recorded end): keep the totals.
    // A stop recorded from the pane stands over the abort the engine reports for it.
    const keep = status === 'done' || a.status === 'stopped'
    return { ...a, status: keep ? a.status : status, tokens, model }
  }
  return {
    ...a,
    waiting: [],
    status,
    endedAt: now,
    durationMs: (a.durationMs ?? 0) + runMs,
    tokens,
    model,
  }
}

export function markFailed(a: AgentRecord, now: number): AgentRecord {
  if (a.status === 'stopped') return a
  return {
    ...a,
    waiting: [],
    status: 'failed',
    endedAt: a.endedAt ?? now,
    durationMs: a.durationMs ?? Math.max(0, now - a.runStartedAt),
  }
}

// ---- Messages ----

/** Resolves a message address (an agent id, an Agent({ name }), or { agentId }) to a known agent id. */
export function resolveAddress(agents: Agents, to: unknown): string | undefined {
  let key: string | undefined
  if (typeof to === 'string') key = to
  else if (to && typeof to === 'object') key = str(to, 'agentId', 'id', 'name', 'to')
  if (!key) return undefined
  if (key === MAIN) return MAIN
  if (agents[key]) return key
  const bare = key.replace(/^agent:/, '')
  if (agents[bare]) return bare
  const byName = Object.values(agents).find(a => a.isSpawned && (a.description === key || a.name === key))
  return byName?.id
}

export function addEdge(agents: Agents, from: string, to: string, now: number): Agents {
  let out = agents
  if (out[from]) out = { ...out, [from]: { ...out[from], messages: [...out[from].messages, { to, at: now }].slice(-MAX_MESSAGES) } }
  if (out[to]) out = { ...out, [to]: { ...out[to], messages: [...out[to].messages, { from, at: now }].slice(-MAX_MESSAGES) } }
  return out
}

// ---- Housekeeping ----

export function isFinished(a: AgentRecord): boolean {
  return a.id !== MAIN && a.status !== 'running'
}

/** Drops finished agents; running ones stay, and an orphan draws at the top level. */
export function clearFinished(agents: Agents, order: string[]): { agents: Agents; order: string[]; removed: number } {
  const keep: Agents = {}
  let removed = 0
  for (const [id, a] of Object.entries(agents)) {
    if (a.isSpawned && isFinished(a)) removed++
    else keep[id] = a
  }
  return { agents: keep, order: order.filter(id => keep[id] !== undefined), removed }
}

export type Counts = { running: number; done: number; failed: number; aborted: number; stopped: number; tokens: number; spawned: number }

export function countsOf(agents: Agents): Counts {
  const c: Counts = { running: 0, done: 0, failed: 0, aborted: 0, stopped: 0, tokens: 0, spawned: 0 }
  for (const a of Object.values(agents)) {
    if (a.id === MAIN || !a.isSpawned) continue
    c.spawned++
    if (a.status in c) c[a.status]++
    c.tokens += totalTokens(a.tokens)
  }
  return c
}

export function anyRunning(agents: Agents): boolean {
  return Object.values(agents).some(a => a.id !== MAIN && a.isSpawned && a.status === 'running')
}


// ---- Spawn caps (0.3.0) ----

export const DEFAULT_CAPS: CapConfig = {
  maxConcurrent: 4,
  maxPerTurn: 8,
  maxPerSession: 40,
  warnAt: 0.75,
  maxReturnedTokens: 150_000,
  waitGraceMs: 4000,
}

export function zeroCounters(): CapCounters {
  return { turn: 0, session: 0, deniedThisTurn: false, warnedThisTurn: false, overrideTurn: false, returnedTotal: 0, returnedWarned: false }
}

/** The counters a new main-loop turn starts with: session totals stay. */
export function newTurn(c: CapCounters): CapCounters {
  return { ...c, turn: 0, deniedThisTurn: false, warnedThisTurn: false, overrideTurn: false }
}

const CAP_FIELDS = ['maxConcurrent', 'maxPerTurn', 'maxPerSession', 'maxReturnedTokens', 'waitGraceMs'] as const

/** The valid cap fields of `over` (a parsed config file, the plugin's settings or the store's overrides). */
export function capFields(over: unknown): Partial<CapConfig> {
  if (!over || typeof over !== 'object') return {}
  const o = over as Record<string, unknown>
  const out: Partial<CapConfig> = {}
  for (const k of CAP_FIELDS) {
    const v = o[k]
    if (typeof v === 'number' && Number.isFinite(v) && v >= 0) out[k] = Math.floor(v)
  }
  const w = o.warnAt
  if (typeof w === 'number' && Number.isFinite(w) && w > 0 && w <= 1) out.warnAt = w
  return out
}

/** Lays the valid fields of `over` (a parsed config file or the store's overrides) on top of `base`. */
export function mergeCaps(base: CapConfig, over: unknown): CapConfig {
  if (!over || typeof over !== 'object') return base
  return { ...base, ...capFields(over) }
}

/** Every cap from the defaults. */
export const DEFAULT_SOURCES: CapSources = {
  maxConcurrent: 'default',
  maxPerTurn: 'default',
  maxPerSession: 'default',
  warnAt: 'default',
  maxReturnedTokens: 'default',
  waitGraceMs: 'default',
}

/** The caps after each layer in turn (later wins), and the layer each value came from. */
export function layerCaps(layers: readonly { source: CapSource; over: unknown }[]): { caps: CapConfig; sources: CapSources } {
  let caps: CapConfig = { ...DEFAULT_CAPS }
  const sources: CapSources = { ...DEFAULT_SOURCES }
  for (const l of layers) {
    const f = capFields(l.over)
    caps = { ...caps, ...f }
    for (const k of Object.keys(f) as (keyof CapConfig)[]) sources[k] = l.source
  }
  return { caps, sources }
}

// ---- The caps in the plugin's settings (0.6.2) ----

/** The plugin's `userConfig` fields for the caps; warnAtPercent is warnAt × 100. */
export const SETTING_FIELDS = ['maxConcurrent', 'maxPerTurn', 'maxPerSession', 'warnAtPercent', 'maxReturnedTokens'] as const
export type SettingField = (typeof SETTING_FIELDS)[number]

/** A `/config` row of this plugin's cap settings: `lk-agent-map.<field>`, or `lk-agent-map@<marketplace>.<field>`. */
export const SETTING_KEY = /^lk-agent-map(@[^.]*)?\.(maxConcurrent|maxPerTurn|maxPerSession|warnAtPercent|maxReturnedTokens)$/

/** Why a value doesn't fit a cap setting, or undefined when it does. */
export function settingProblem(field: string, value: unknown): string | undefined {
  if (field === 'warnAtPercent') {
    return typeof value === 'number' && Number.isFinite(value) && value >= 1 && value <= 100 ? undefined : 'agent-map: warnAtPercent takes a number from 1 to 100'
  }
  if (!(SETTING_FIELDS as readonly string[]).includes(field)) return undefined
  return typeof value === 'number' && Number.isInteger(value) && value >= 0 ? undefined : 'agent-map: ' + field + ' takes a whole number, 0 or more (0 means no cap)'
}

/**
 * The settings' values by field: this plugin's `/config` rows when listed, else the values
 * `register(on, options)` got.
 */
export function settingValues(rows: unknown, options: unknown): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  if (options && typeof options === 'object') {
    const o = options as Record<string, unknown>
    for (const f of SETTING_FIELDS) if (f in o) out[f] = o[f]
  }
  if (Array.isArray(rows)) {
    for (const r of rows) {
      const m = r && typeof r === 'object' ? SETTING_KEY.exec(String((r as { key?: unknown }).key)) : null
      if (m) out[m[2]] = (r as { value?: unknown }).value
    }
  }
  return out
}

/** The caps the settings set: valid values that differ from the defaults (options arrive with the defaults filled in). */
export function settingsCaps(values: Record<string, unknown>): Partial<CapConfig> {
  const out: Partial<CapConfig> = {}
  for (const f of SETTING_FIELDS) {
    const v = values[f]
    if (v === undefined || settingProblem(f, v) !== undefined) continue
    const key: keyof CapConfig = f === 'warnAtPercent' ? 'warnAt' : f
    const n = f === 'warnAtPercent' ? (v as number) / 100 : (v as number)
    if (n !== DEFAULT_CAPS[key]) out[key] = n
  }
  return out
}

/** Parses a config file's text; anything that isn't a JSON object is ignored. */
export function parseCapFile(text: unknown): unknown {
  if (typeof text !== 'string' || !text.trim()) return undefined
  try {
    const v = JSON.parse(text)
    return v && typeof v === 'object' && !Array.isArray(v) ? v : undefined
  } catch {
    return undefined
  }
}

export const CAP_NAMES: Record<CapKind, string> = {
  concurrent: 'concurrency cap',
  turn: 'per-turn spawn cap',
  session: 'per-session spawn cap',
}

const CAP_MAX: Record<CapKind, keyof CapConfig> = { concurrent: 'maxConcurrent', turn: 'maxPerTurn', session: 'maxPerSession' }

export type CapUse = { kind: CapKind; n: number; max: number }

/** Running subagents (forks and teammates included). */
export function runningCount(agents: Agents): number {
  let n = 0
  for (const a of Object.values(agents)) if (a.id !== MAIN && a.isSpawned && a.status === 'running') n++
  return n
}

/** Where each cap stands before a spawn: running agents (plus spawns in flight), this turn's spawns, the session's. */
export function capUses(running: number, c: CapCounters, caps: CapConfig): CapUse[] {
  return [
    { kind: 'concurrent', n: running, max: caps.maxConcurrent },
    { kind: 'turn', n: c.turn, max: caps.maxPerTurn },
    { kind: 'session', n: c.session, max: caps.maxPerSession },
  ]
}

/** The first cap one more spawn would go past; a turn-exempt spawn (fork, teammate) skips the per-turn cap. */
export function capBreach(uses: CapUse[], countsTurn = true): CapUse | undefined {
  return uses.find(u => u.max > 0 && u.n >= u.max && (countsTurn || u.kind !== 'turn'))
}

/** The first cap at or past warnAt once this spawn is counted. */
export function capNear(uses: CapUse[], warnAt: number, countsTurn = true): CapUse | undefined {
  return uses
    .filter(u => countsTurn || u.kind !== 'turn')
    .map(u => ({ ...u, n: u.n + 1 }))
    .find(u => u.max > 0 && u.n / u.max >= warnAt)
}

/** True while a cap stands at or past warnAt (for the band's color). */
export function nearAnyCap(uses: CapUse[], warnAt: number): boolean {
  return uses.some(u => u.max > 0 && u.n / u.max >= warnAt)
}

export function denyText(u: CapUse): string {
  return (
    'agent-map: ' + CAP_NAMES[u.kind] + ' reached (' + u.n + '/' + u.max + '). Wait for running subagents to return, or batch the work into fewer agents. ' +
    'The user can raise it with /agent-map cap ' + u.kind + ' <n>.'
  )
}

export function nearText(u: CapUse): string {
  const what = u.kind === 'concurrent' ? 'running' : u.kind === 'turn' ? 'spawned this turn' : 'spawned this session'
  return 'agents ' + u.n + '/' + u.max + ' ' + what + ', near the ' + CAP_NAMES[u.kind]
}

export const OVERRIDE_RE = /\[cap-override:\s*([^\]]*)\]/i

/** The reason of a `[cap-override: <reason>]` marker in any of the texts, if there is one. */
export function overrideReason(...texts: unknown[]): string | undefined {
  for (const t of texts) {
    if (typeof t !== 'string') continue
    const m = OVERRIDE_RE.exec(t)
    if (m) return m[1].replace(/\s+/g, ' ').trim() || 'no reason given'
  }
  return undefined
}

export function stripOverride(s: string): string {
  return s.replace(new RegExp(OVERRIDE_RE.source, 'gi'), '').replace(/\s{2,}/g, ' ').trim()
}

export const ASK_ALLOW_ONE = 'Allow this one'
export const ASK_ALLOW_TURN = 'Allow the rest of the turn'
export const ASK_DENY = 'Deny'

export function askText(reason: string): string {
  return 'agent-map: ' + reason + '. Allow one more agent beyond the cap?'
}

export type CapCommandKind = CapKind | 'returned' | 'warn' | 'grace'
export type CapCommand = { kind: CapCommandKind; value: number } | { error: string }

const CAP_KEY: Record<string, keyof CapConfig> = {
  concurrent: 'maxConcurrent',
  turn: 'maxPerTurn',
  session: 'maxPerSession',
  returned: 'maxReturnedTokens',
  warn: 'warnAt',
  grace: 'waitGraceMs',
}

export const CAP_USAGE =
  'Usage: /agent-map cap [concurrent <n> | turn <n> | session <n> | returned <k> | warn <0.1-1> | grace <ms> | reset [<kind>]] (0 turns a cap off)'

const isCapWord = (kind: string | undefined): kind is string => !!kind && Object.prototype.hasOwnProperty.call(CAP_KEY, kind)

/** `/agent-map cap concurrent 6`, `cap returned 200` (thousands of tokens) or `cap returned 200k`, `cap warn 0.8`. */
export function parseCapCommand(args: readonly string[]): CapCommand {
  const kind = args[0]
  const raw = (args[1] ?? '').toLowerCase()
  if (!isCapWord(kind) || !raw) return { error: CAP_USAGE }
  const m = /^(\d+(?:\.\d+)?)(k)?$/.exec(raw)
  if (!m) return { error: CAP_USAGE }
  let value = Number(m[1])
  if (kind === 'warn') {
    if (!(value > 0 && value <= 1)) return { error: 'warn takes a share between 0.1 and 1, such as 0.75' }
    return { kind: 'warn', value }
  }
  if (kind === 'returned') value = m[2] || value < 1000 ? value * 1000 : value
  return { kind: kind as CapKind | 'returned' | 'grace', value: Math.floor(value) }
}

export function capKeyOf(kind: CapKind | 'returned' | 'warn' | 'grace'): keyof CapConfig {
  return CAP_KEY[kind]
}

/** `/agent-map cap reset [kind]`: the saved override to clear, every one without a kind. */
export function parseCapReset(args: readonly string[]): { kind?: CapCommandKind; key?: keyof CapConfig } | { error: string } {
  const kind = args[1]
  if (kind === undefined) return {}
  if (!isCapWord(kind) || args.length > 2) return { error: CAP_USAGE }
  return { kind: kind as CapCommandKind, key: CAP_KEY[kind] }
}

export function capMaxOf(caps: CapConfig, kind: CapKind): number {
  return caps[CAP_MAX[kind]]
}

// ---- Context cost of results (0.3.0) ----

/** Tokens a text costs, estimated as characters / 4. */
export function estimateTokens(text: string): number {
  return text ? Math.ceil(text.length / 4) : 0
}

/** The text of a tool result as the model reads it: core's `text`, else the result itself. */
export function resultText(r: unknown): string {
  if (!r || typeof r !== 'object') return typeof r === 'string' ? r : ''
  const o = r as Record<string, unknown>
  if (o.deny) return ''
  if (typeof o.text === 'string') return o.text
  const res = o.result
  if (typeof res === 'string') return res
  if (res === undefined || res === null) return ''
  if (typeof res === 'object') {
    const content = (res as Record<string, unknown>).content
    if (Array.isArray(content)) {
      const joined = content
        .map(b => (b && typeof b === 'object' && typeof (b as { text?: unknown }).text === 'string' ? (b as { text: string }).text : ''))
        .join('')
      if (joined) return joined
    }
  }
  try {
    return JSON.stringify(res)
  } catch {
    return ''
  }
}

export function addReturned(a: AgentRecord, tokens: number): AgentRecord {
  return { ...a, returnedTokens: (a.returnedTokens ?? 0) + tokens }
}

// ---- Lifecycle log (0.3.0) ----

export const MAX_LOG = 200

export function addLog(list: readonly LogEntry[], entry: LogEntry): LogEntry[] {
  return [...list, entry].slice(-MAX_LOG)
}

files.hooks/format.ts:
// Pure text layout for agent-map: the tree rows the pane draws and the
// /agent-map text command prints, the band's one line, and the cards' critter avatar.
//
// Colors are theme keys (suggestion, success, error, claude, permission, inactive) that the host
// tunes for light and dark; Svg markup cannot read them, so the critter uses fixed hexes.
import type { AgentRecord, AgentStatus, CapConfig, CapCounters, LogEntry } from '../types'
import type { Tone } from './kit'
import { DEFAULT_CAPS, MAIN, capUses, countsOf, idleMs, isStuck, nearAnyCap, runningCount, totalTokens, zeroCounters } from './model'
import type { Agents, Counts } from './model'

export const LABEL_MAX = 24
export const PROMPT_EXCERPT = 200
/** The width /agent-map text lays out to. */
export const TEXT_COLUMNS = 120

export type RowKind = 'header' | 'agent' | 'activity' | 'msg' | 'detail' | 'empty' | 'lane' | 'log'

export type Row = {
  kind: RowKind
  /** The agent the row belongs to. */
  id?: string
  /** Tree drawing in front of the row: ├─, └─, │ and spaces. */
  prefix: string
  glyph?: string
  /** A theme key for the glyph. */
  color?: string
  dim?: boolean
  body: string
  /** A status note after the body, such as `⏸ waiting: Bash` or `⚠ idle 5m`. */
  flag?: string
  flagColor?: string
  /** The agent row of a running agent: the pane gives it a Stop button. */
  canStop?: boolean
}

export const FORK_MARK = '⑂'
export const TEAMMATE_MARK = '◇'
export const DEFAULT_STUCK_MS = 300_000

export function fmtTokens(n: number): string {
  const v = Math.max(0, Math.round(n || 0))
  if (v < 1000) return String(v)
  const k = Math.round(v / 1000)
  if (k < 1000) return k + 'k'
  return (v / 1e6).toFixed(1) + 'M'
}

const pad2 = (n: number) => (n < 10 ? '0' : '') + n

export function fmtElapsed(ms: number): string {
  const s = Math.max(0, Math.floor((ms || 0) / 1000))
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const sec = s % 60
  return h > 0 ? h + ':' + pad2(m) + ':' + pad2(sec) : pad2(m) + ':' + pad2(sec)
}

export function shortModel(model: string): string {
  const m = (model || '').toLowerCase()
  for (const k of ['opus', 'sonnet', 'haiku', 'fable']) if (m.includes(k)) return k
  if (!m) return '?'
  return m.replace(/^claude-/, '').slice(0, 12)
}

export function elapsedOf(a: AgentRecord, now: number): number {
  if (a.status === 'running') return (a.durationMs ?? 0) + Math.max(0, now - a.runStartedAt)
  if (typeof a.durationMs === 'number') return a.durationMs
  return Math.max(0, (a.endedAt ?? now) - a.startedAt)
}

export function glyphOf(status: AgentStatus): { glyph: string; color?: string; dim?: boolean } {
  switch (status) {
    case 'running':
      return { glyph: '●', color: 'success' }
    case 'done':
      return { glyph: '✓', color: 'success' }
    case 'failed':
      return { glyph: '✗', color: 'error' }
    case 'stopped':
      return { glyph: '■', color: 'claude' }
    default:
      return { glyph: '○', color: 'inactive', dim: true }
  }
}

const oneLine = (s: string) => (s || '').replace(/\s+/g, ' ').trim()

export function labelOf(a: AgentRecord | undefined, fallback = ''): string {
  if (!a) return fallback
  return oneLine(a.description) || a.name || a.id
}

export function cut(s: string, n: number): string {
  const chars = Array.from(s)
  return chars.length <= n ? s : chars.slice(0, Math.max(0, n)).join('')
}

const len = (s: string) => Array.from(s).length

/** Breaks text into pieces of at most `width` characters, at spaces where it can. */
export function wrapText(s: string, width: number): string[] {
  const w = Math.max(8, width)
  const out: string[] = []
  let rest = oneLine(s)
  while (len(rest) > w) {
    const head = cut(rest, w)
    const sp = head.lastIndexOf(' ')
    const take = sp > w / 3 ? head.slice(0, sp) : head
    out.push(take)
    rest = rest.slice(take.length).trimStart()
  }
  if (rest || out.length === 0) out.push(rest)
  return out
}

export function markOf(a: AgentRecord): string {
  return (a.isFork ? FORK_MARK + ' ' : '') + (a.isTeammate ? TEAMMATE_MARK + ' ' : '')
}

export function fmtIdle(ms: number): string {
  const m = Math.floor(ms / 60_000)
  if (m >= 60) return Math.floor(m / 60) + 'h' + (m % 60 ? (m % 60) + 'm' : '')
  if (m >= 1) return m + 'm'
  return Math.floor(ms / 1000) + 's'
}

/** The note on an agent's row: waiting on the person, idle too long, or muted. */
export function flagOf(a: AgentRecord, now: number, stuckAfterMs: number): { text: string; color?: string } | undefined {
  if (a.status !== 'running') return a.status === 'stopped' && a.stoppedBy ? { text: 'by ' + a.stoppedBy } : undefined
  if (a.waiting?.length) return { text: '⏸ waiting: ' + Array.from(new Set(a.waiting.map(w => w.tool))).join(', '), color: 'claude' }
  if (a.muted) return { text: '⊘ muted', color: 'permission' }
  if (isStuck(a, now, stuckAfterMs)) return { text: '⚠ idle ' + fmtIdle(idleMs(a, now)), color: 'error' }
  return undefined
}

/** The agent's line after its glyph, sized so prefix + glyph + line (+ reserved room) fits in `columns`. */
export function agentLine(a: AgentRecord, now: number, columns: number, prefixLen: number, note = ''): string {
  const fields = [
    a.name || 'agent',
    shortModel(a.model),
    fmtElapsed(elapsedOf(a, now)),
    a.toolCalls + ' tools',
    fmtTokens(totalTokens(a.tokens)) + ' tok',
    ...(note ? [note] : []),
  ].join('  ')
  const room = columns - prefixLen - 2 - 2 - len(fields)
  const labelMax = Math.max(4, Math.min(LABEL_MAX, room))
  const line = markOf(a) + cut(labelOf(a), labelMax).trimEnd() + '  ' + fields
  return cut(line, Math.max(4, columns - prefixLen - 2))
}

function messageRows(agents: Agents, a: AgentRecord, prefix: string, columns: number): Row[] {
  const byTarget = new Map<string, number>()
  for (const m of a.messages) if (m.to) byTarget.set(m.to, (byTarget.get(m.to) ?? 0) + 1)
  const rows: Row[] = []
  for (const [to, n] of byTarget) {
    const target = to === MAIN ? 'main' : labelOf(agents[to], to)
    const body = cut('→ msg to ' + cut(target, LABEL_MAX) + (n > 1 ? ' x' + n : ''), Math.max(4, columns - len(prefix)))
    rows.push({ kind: 'msg', id: a.id, prefix, dim: true, body })
  }
  return rows
}

function detailRows(agents: Agents, a: AgentRecord, prefix: string, now: number, columns: number): Row[] {
  return detailLines(agents, a, now, columns - len(prefix)).map(body => ({ kind: 'detail' as const, id: a.id, prefix, dim: true, body }))
}

/** An agent's details, wrapped to `columns`: description, prompt, tools, tokens, status and model. */
export function detailLines(agents: Agents, a: AgentRecord, now: number, columns: number): string[] {
  const width = Math.max(8, columns)
  const tools = Object.entries(a.toolsByName)
    .sort((x, y) => y[1] - x[1])
    .map(([k, v]) => k + ' ' + v)
    .join(' · ')
  const t = a.tokens
  const parent = a.parent === MAIN || !a.parent ? 'main' : labelOf(agents[a.parent], a.parent)
  const flags = [
    a.isFork ? 'fork' : '',
    a.isTeammate ? 'teammate' : '',
    a.isBackground ? 'background' : '',
    a.muted ? 'muted' : '',
    a.stoppedBy ? 'stopped by ' + a.stoppedBy : '',
  ].filter(Boolean)
  const lines = [
    'description: ' + (oneLine(a.description) || '-'),
    'prompt: ' + (cut(oneLine(a.prompt), PROMPT_EXCERPT) || '-'),
    'tools: ' + (tools || 'none') + (a.lastTool ? ' (last ' + a.lastTool + ')' : ''),
    ...(a.activity ? ['last: ' + a.activity] : []),
    'tokens: in ' + fmtTokens(t.input) + ' · out ' + fmtTokens(t.output) + ' · cache read ' + fmtTokens(t.cacheRead) + ' · cache write ' + fmtTokens(t.cacheCreate),
    'status: ' + a.status + ' · ' + fmtElapsed(elapsedOf(a, now)) + ' · ' + a.requests + ' requests · from ' + parent + (flags.length ? ' · ' + flags.join(', ') : ''),
    'model: ' + (a.model || '?') + ((a.returnedTokens ?? 0) > 0 ? ' · ' + returnedNote(agents, a) : ''),
  ]
  return lines.flatMap(l => wrapText(l, width))
}

export type TreeOptions = {
  now: number
  columns: number
  expanded?: readonly string[]
  /** Idle threshold for the `⚠ idle` note; 0 turns it off. */
  stuckAfterMs?: number
  /** Columns kept free on a running agent's row (the pane's Stop button). */
  reserve?: number
}

/** The spawned agents to draw, in spawn order. */
export function visibleIds(agents: Agents, order: readonly string[]): string[] {
  const ids = order.filter(id => id !== MAIN && agents[id]?.isSpawned)
  for (const id of Object.keys(agents)) if (id !== MAIN && agents[id].isSpawned && !ids.includes(id)) ids.push(id)
  return ids
}

/** Every row of the map: the main loop's header, then the agents as a tree. */
export function buildRows(agents: Agents, order: readonly string[], opts: TreeOptions): Row[] {
  const { now, columns } = opts
  const expanded = new Set(opts.expanded ?? [])
  const stuckAfterMs = opts.stuckAfterMs ?? DEFAULT_STUCK_MS
  const reserve = Math.max(0, opts.reserve ?? 0)
  const agentRow = (id: string, lead: string): Row => {
    const a = agents[id]
    const g = glyphOf(a.status)
    const running = a.status === 'running'
    const flag = flagOf(a, now, stuckAfterMs)
    const flagText = flag ? '  ' + flag.text : ''
    const room = columns - (running ? reserve : 0)
    const body = agentLine(a, now, Math.max(len(lead) + 8, room - len(flagText)), len(lead), returnedNote(agents, a))
    const row: Row = { kind: 'agent', id, prefix: lead, glyph: g.glyph, color: g.color, dim: g.dim, body, canStop: running }
    if (flag) {
      row.flag = cut(flagText, Math.max(0, room - len(lead) - 2 - len(body)))
      if (flag.color) row.flagColor = flag.color
      if (!row.flag.trim()) delete row.flag
    }
    return row
  }
  const activityRow = (a: AgentRecord, prefix: string): Row[] =>
    a.status === 'running' && a.activity
      ? [{ kind: 'activity', id: a.id, prefix, dim: true, body: cut('⋯ ' + a.activity, Math.max(4, columns - len(prefix))) }]
      : []
  const main = agents[MAIN]
  const header =
    'main (orchestrator) · ' + fmtTokens(totalTokens(main?.tokens)) + ' tok · ' + (main?.toolCalls ?? 0) + ' tools'
  const mainWaits = main?.waiting?.length ? ' · ⏸ waiting: ' + Array.from(new Set(main.waiting.map(w => w.tool))).join(', ') : ''
  const rows: Row[] = [{ kind: 'header', id: MAIN, prefix: '', body: cut(header + mainWaits, Math.max(8, columns)) }]
  const ids = visibleIds(agents, order)
  const shown = new Set(ids)
  const parentOf = (id: string) => {
    const p = agents[id].parent
    return p && p !== id && shown.has(p) ? p : MAIN
  }
  if (main) rows.push(...messageRows(agents, main, ids.length ? '│   ' : '', columns))
  if (ids.length === 0) {
    rows.push({ kind: 'empty', prefix: '', dim: true, body: 'no subagents yet' })
    return rows
  }
  const placed = new Set<string>()
  const walk = (pid: string, prefix: string) => {
    const kids = ids.filter(id => !placed.has(id) && parentOf(id) === pid)
    kids.forEach(id => placed.add(id))
    kids.forEach((id, i) => {
      const a = agents[id]
      const last = i === kids.length - 1
      const lead = prefix + (last ? '└─ ' : '├─ ')
      const cont = prefix + (last ? '    ' : '│   ')
      rows.push(agentRow(id, lead))
      rows.push(...activityRow(a, cont))
      if (expanded.has(id)) rows.push(...detailRows(agents, a, cont + '  ', now, columns))
      rows.push(...messageRows(agents, a, cont, columns))
      walk(id, cont)
    })
  }
  walk(MAIN, '')
  // A parent cycle leaves agents unplaced: draw them at the top level
  for (const id of ids) {
    if (placed.has(id)) continue
    placed.add(id)
    rows.push(agentRow(id, '└─ '))
    rows.push(...activityRow(agents[id], '    '))
  }
  return rows
}

export function rowText(r: Row): string {
  return r.prefix + (r.glyph ? r.glyph + ' ' : '') + r.body + (r.flag ?? '')
}

export function treeText(agents: Agents, order: readonly string[], now: number, columns = TEXT_COLUMNS, stuckAfterMs = DEFAULT_STUCK_MS): string {
  return buildRows(agents, order, { now, columns, stuckAfterMs }).map(rowText).join('\n')
}

export type BandExtra = { caps?: CapConfig; counters?: CapCounters }

/** Where the caps stand: a spawn was denied this turn or a cap is reached, past warnAt, or neither. */
export type BandState = 'ok' | 'near cap' | 'at cap'

/** One chip of the band: its whole text (glyph included) and its tone. */
export type BandChip = { text: string; tone: Tone }

/** The theme key of each state, as the state chip draws it (near cap is 'claude', not the warning key). */
export const BAND_COLORS: Record<BandState, string> = { ok: 'success', 'near cap': 'claude', 'at cap': 'error' }
const BAND_TONES: Record<BandState, Tone> = { ok: 'ok', 'near cap': 'accent', 'at cap': 'danger' }

/** The band's chips: `● 3/4 running`, `✓ 5 done`, `✗ 1` and the `● ok` state chip; a zero count is muted. */
export function bandChips(c: Counts, state: BandState, caps: CapConfig = DEFAULT_CAPS): BandChip[] {
  const running = caps.maxConcurrent > 0 ? c.running + '/' + caps.maxConcurrent : String(c.running)
  return [
    { text: '● ' + running + ' running', tone: c.running > 0 ? 'info' : 'muted' },
    { text: '✓ ' + c.done + ' done', tone: c.done > 0 ? 'ok' : 'muted' },
    { text: '✗ ' + c.failed, tone: c.failed > 0 ? 'danger' : 'muted' },
    { text: '● ' + state, tone: BAND_TONES[state] },
  ]
}

/** The band's quiet right-hand side: aborted and stopped counts, tokens, and results returned to main. */
export function bandRight(c: Counts, extra: BandExtra = {}): string[] {
  const returned = extra.counters?.returnedTotal ?? 0
  const out: string[] = []
  if (c.aborted > 0) out.push('○ ' + c.aborted + ' aborted')
  if (c.stopped > 0) out.push('■ ' + c.stopped + ' stopped')
  out.push(fmtTokens(c.tokens) + ' tok')
  // Results under 1k tokens are noise next to a context window
  if (returned >= 1000) out.push('results ' + fmtTokens(returned) + ' → main')
  return out
}

/** The band as one line of text: `agents  ● 3/4 running  ✓ 5 done  ✗ 1  ● ok  412k tok · results 96k → main`. */
export function bandText(c: Counts, extra: BandExtra = {}, state: BandState = 'ok'): string {
  const chips = bandChips(c, state, extra.caps ?? DEFAULT_CAPS).map(x => x.text)
  return ['agents', ...chips, bandRight(c, extra).join(' · ')].join('  ')
}

/** True once the results returned to main pass warnAt of maxReturnedTokens. */
export function returnedNear(caps: CapConfig, counters: CapCounters): boolean {
  return caps.maxReturnedTokens > 0 && counters.returnedTotal >= caps.warnAt * caps.maxReturnedTokens
}

/** The cap state: at cap once a spawn was denied this turn or a cap is reached, near cap past warnAt, else ok. */
export function bandStateOf(extra: BandExtra = {}, near = false, at = false): BandState {
  if (extra.counters?.deniedThisTurn || at) return 'at cap'
  return near ? 'near cap' : 'ok'
}

/** The state's theme key. */
export function bandColor(state: BandState): string {
  return BAND_COLORS[state]
}

export type Band = { text: string; color: string; state: BandState; chips: BandChip[]; right: string[]; counts: Counts }

export function bandOf(agents: Agents, extra: BandExtra = {}): Band {
  const counts = countsOf(agents)
  const caps = extra.caps ?? DEFAULT_CAPS
  const counters = extra.counters ?? zeroCounters()
  const uses = capUses(runningCount(agents), counters, caps)
  const near = nearAnyCap(uses, caps.warnAt) || returnedNear(caps, counters)
  const at = uses.some(u => u.max > 0 && u.n >= u.max) || (caps.maxReturnedTokens > 0 && counters.returnedTotal >= caps.maxReturnedTokens)
  const state = bandStateOf(extra, near, at)
  return { text: bandText(counts, extra, state), color: bandColor(state), state, chips: bandChips(counts, state, caps), right: bandRight(counts, extra), counts }
}

// ---- Cards view (0.3.0) ----

export const CARD_LABEL = 32

const pad2c = (n: number) => (n < 10 ? '0' : '') + n

/** A wall-clock time in the runtime's local zone: `10:31`, or `10:31:05` with seconds. */
export function fmtClock(ms: number, seconds = false): string {
  const d = new Date(ms)
  const hm = pad2c(d.getHours()) + ':' + pad2c(d.getMinutes())
  return seconds ? hm + ':' + pad2c(d.getSeconds()) : hm
}

export function returnedNote(agents: Agents, a: AgentRecord): string {
  const n = a.returnedTokens ?? 0
  if (n <= 0) return ''
  const to = a.parent === MAIN || !a.parent ? 'main' : cut(labelOf(agents[a.parent], a.parent), 16)
  return '→ ' + fmtTokens(n) + ' to ' + to
}

/** Running agents first, then the ones waiting on the person, then the finished. */
export function cardOrder(agents: Agents, order: readonly string[]): string[] {
  const ids = visibleIds(agents, order)
  const rank = (a: AgentRecord) => (a.status !== 'running' ? 2 : a.waiting?.length ? 1 : 0)
  return ids
    .map((id, i) => ({ id, i, r: rank(agents[id]) }))
    .sort((x, y) => x.r - y.r || x.i - y.i)
    .map(x => x.id)
}

/** `spawned 10:31 → running 00:57 → ⏸ waiting (Bash) → done 10:38` */
export function lifecycleLine(a: AgentRecord, now: number, stuckAfterMs: number): string {
  const parts = ['spawned ' + fmtClock(a.startedAt), 'running ' + fmtElapsed(elapsedOf(a, now))]
  if (a.status === 'running') {
    if (a.waiting?.length) parts.push('⏸ waiting (' + Array.from(new Set(a.waiting.map(w => w.tool))).join(', ') + ')')
    else if (a.muted) parts.push('⊘ muted')
    else if (isStuck(a, now, stuckAfterMs)) parts.push('⚠ idle ' + fmtIdle(idleMs(a, now)))
  } else {
    parts.push(a.status + ' ' + fmtClock(a.endedAt ?? now) + (a.status === 'stopped' && a.stoppedBy ? ' by ' + a.stoppedBy : ''))
  }
  return parts.join(' → ')
}

export type Card = {
  id: string
  glyph: string
  color?: string
  /** label · type · model, with the fork or teammate mark in front. */
  title: string
  lifecycle: string
  stats: string
  parent: string
  canStop: boolean
}

/** One card's four lines, each cut to `width` (the inside of the card's border). */
export function cardOf(agents: Agents, a: AgentRecord, now: number, width: number, stuckAfterMs = DEFAULT_STUCK_MS): Card {
  const w = Math.max(8, width)
  const g = glyphOf(a.status)
  const title = markOf(a) + cut(labelOf(a), CARD_LABEL).trimEnd() + ' · ' + (a.name || 'agent') + ' · ' + shortModel(a.model)
  const stats = [
    a.toolCalls + ' tool' + (a.toolCalls === 1 ? '' : 's'),
    a.activity ? 'last ' + a.activity : '',
    fmtTokens(totalTokens(a.tokens)) + ' tok',
    returnedNote(agents, a),
  ]
    .filter(Boolean)
    .join(' · ')
  const parent = 'from ' + (a.parent === MAIN || !a.parent ? 'main' : labelOf(agents[a.parent], a.parent))
  const running = a.status === 'running'
  return {
    id: a.id,
    glyph: g.glyph,
    color: g.color,
    // Room for ' ' + glyph after the title
    title: cut(title, w - 2),
    lifecycle: cut(lifecycleLine(a, now, stuckAfterMs), w),
    stats: cut(stats, w),
    parent: cut(parent, running ? Math.max(4, w - 14) : w),
    canStop: running,
  }
}

export function cardsOf(agents: Agents, order: readonly string[], now: number, columns: number, stuckAfterMs = DEFAULT_STUCK_MS): Card[] {
  // A card's border and padding take 4 columns
  return cardOrder(agents, order).map(id => cardOf(agents, agents[id], now, columns - 4, stuckAfterMs))
}

/** The cards as text, each in a rounded border, for /agent-map text and tests. */
export function cardsText(agents: Agents, order: readonly string[], now: number, columns = TEXT_COLUMNS, stuckAfterMs = DEFAULT_STUCK_MS): string {
  const cards = cardsOf(agents, order, now, columns, stuckAfterMs)
  if (cards.length === 0) return 'no subagents yet'
  const inner = columns - 4
  const line = (s: string) => '│ ' + s + ' '.repeat(Math.max(0, inner - len(s))) + ' │'
  return cards
    .map(c =>
      [
        '╭' + '─'.repeat(columns - 2) + '╮',
        line(c.title + ' ' + c.glyph),
        line(c.lifecycle),
        line(c.stats),
        line(c.parent + (c.canStop ? '  [Stop]' : '')),
        '╰' + '─'.repeat(columns - 2) + '╯',
      ].join('\n'),
    )
    .join('\n')
}

// ---- Team view (0.3.0) ----

export function laneHeader(agents: Agents, ids: readonly string[], title: string): string {
  const n = { running: 0, done: 0, failed: 0, other: 0 }
  for (const id of ids) {
    const s = agents[id].status
    if (s === 'running') n.running++
    else if (s === 'done') n.done++
    else if (s === 'failed') n.failed++
    else n.other++
  }
  const parts = [n.running + ' running', n.done + ' done']
  if (n.failed) parts.push(n.failed + ' failed')
  if (n.other) parts.push(n.other + ' ended')
  return title + ': ' + parts.join(' · ')
}

/**
 * Agents grouped by parent into lanes: the main loop's children first, then
 * each agent's children in a lane indented under its parent's, and the
 * teammates (◇) in a lane of their own.
 */
export function teamRows(agents: Agents, order: readonly string[], opts: TreeOptions): Row[] {
  const { now, columns } = opts
  const stuckAfterMs = opts.stuckAfterMs ?? DEFAULT_STUCK_MS
  const reserve = Math.max(0, opts.reserve ?? 0)
  const ids = visibleIds(agents, order)
  const shown = new Set(ids)
  const parentOf = (id: string) => {
    const p = agents[id].parent
    return p && p !== id && shown.has(p) ? p : MAIN
  }
  const rows: Row[] = []
  if (ids.length === 0) return [{ kind: 'empty', prefix: '', dim: true, body: 'no subagents yet' }]
  const agentRow = (id: string, lead: string): Row => {
    const a = agents[id]
    const g = glyphOf(a.status)
    const running = a.status === 'running'
    const flag = flagOf(a, now, stuckAfterMs)
    const tail = flag ? '  ' + flag.text : ''
    const room = columns - (running ? reserve : 0)
    const body = agentLine(a, now, Math.max(len(lead) + 8, room - len(tail)), len(lead), returnedNote(agents, a))
    const row: Row = { kind: 'agent', id, prefix: lead, glyph: g.glyph, color: g.color, dim: g.dim, body, canStop: running }
    const t = cut(tail, Math.max(0, room - len(lead) - 2 - len(body)))
    if (t.trim()) {
      row.flag = t
      if (flag?.color) row.flagColor = flag.color
    }
    return row
  }
  const done = new Set<string>()
  const lane = (pid: string, depth: number, members: string[], title: string) => {
    if (members.length === 0) return
    const indent = '  '.repeat(depth)
    rows.push({ kind: 'lane', id: pid, prefix: indent, body: cut(laneHeader(agents, members, title), Math.max(4, columns - len(indent))) })
    for (const id of members) {
      done.add(id)
      rows.push(agentRow(id, indent + '  '))
    }
  }
  const walk = (pid: string, depth: number) => {
    const kids = ids.filter(id => !done.has(id) && !agents[id].isTeammate && parentOf(id) === pid)
    const title = 'team of ' + (pid === MAIN ? 'main' : cut(labelOf(agents[pid], pid), LABEL_MAX))
    lane(pid, depth, kids, title)
    for (const id of kids) walk(id, depth + 1)
  }
  walk(MAIN, 0)
  const mates = ids.filter(id => !done.has(id) && agents[id].isTeammate)
  lane('teammates', 0, mates, 'teammates')
  for (const id of mates) walk(id, 1)
  // A parent cycle leaves agents out: they get a lane of their own
  lane('other', 0, ids.filter(id => !done.has(id)), 'unattached')
  return rows
}

export function teamText(agents: Agents, order: readonly string[], now: number, columns = TEXT_COLUMNS, stuckAfterMs = DEFAULT_STUCK_MS): string {
  return teamRows(agents, order, { now, columns, stuckAfterMs }).map(rowText).join('\n')
}

// ---- Lifecycle log (0.3.0) ----

export const LOG_TEXT_LINES = 40
export const LOG_PANE_LINES = 12

export function logLine(e: LogEntry): string {
  return fmtClock(e.at, true) + ' ' + e.kind + ' ' + e.label + (e.text ? ' · ' + e.text : '')
}

export function logText(log: readonly LogEntry[], n = LOG_TEXT_LINES): string {
  if (log.length === 0) return 'agent-map log: no lifecycle events yet'
  return log.slice(-n).map(logLine).join('\n')
}

export function logRows(log: readonly LogEntry[], columns: number, n = LOG_PANE_LINES): Row[] {
  const rows: Row[] = [{ kind: 'lane', prefix: '', body: 'log (last ' + Math.min(n, log.length) + ')' }]
  if (log.length === 0) rows.push({ kind: 'log', prefix: '', dim: true, body: 'no lifecycle events yet' })
  for (const e of log.slice(-n)) rows.push({ kind: 'log', id: e.id, prefix: '', dim: true, body: cut(logLine(e), Math.max(4, columns)) })
  return rows
}

// ---- Card look (0.5.0): the effort word and the critter avatar ----

/** An effort as the card shows it: the word, its tone, and the critter's hat color. */
export type EffortLook = { word: string; tone: Tone; hat: string }

const EFFORTS: Record<string, EffortLook> = {
  low: { word: 'light', tone: 'ok', hat: '#22A35A' },
  medium: { word: 'medium', tone: 'info', hat: '#3B82F6' },
  high: { word: 'careful', tone: 'accent', hat: '#D9901A' },
  xhigh: { word: 'thorough', tone: 'accent', hat: '#E5484D' },
  max: { word: 'max', tone: 'danger', hat: '#E5484D' },
}
const NO_EFFORT: EffortLook = { word: '', tone: 'info', hat: '#64748B' }

/** low → light, medium → medium, high → careful, xhigh → thorough, max → max; anything else draws no word. */
export function effortLook(effort: string): EffortLook {
  return EFFORTS[String(effort || '').trim().toLowerCase()] ?? NO_EFFORT
}

/** The critter's state: a pennant while running, X eyes when failed, faded once finished. */
export type CritterState = 'running' | 'waiting' | 'done' | 'failed' | 'idle'

const CRITTER = { body: '#C96F4A', outline: '#8A4A32', eye: '#1A1A1A', crown: '#8B5CF6', stick: '#8A4A32', pennant: '#E5484D' }
export const CRITTER_SIZE = 44

// 12×12 cells. H = hat (or the main loop's crown), O = outline, B = body, E = eye, S = stick, P = pennant.
const HAT = ['...HHH......', '..HHHHH.....', '.HHHHHHH....']
const CROWN = ['.H..H..H....', '.HHHHHHH....', '.HHHHHHH....']
const BODY = [
  '.OOOOOOO....',
  'OBBBBBBBO...',
  'OBEBBBEBO...',
  'OBEBBBEBO...',
  'OBBBBBBBB...',
  'OBBBBBBBO...',
  '.OBBBBBO....',
  '.OO...OO....',
  '.OO...OO....',
]
const POLE = ['.........SPP', '.........SPP', '.........SP.', '.........S..', '.........S..', '.........S..', '.........S..', '.........S..']

const critterCache = new Map<string, string>()

/**
 * The critter avatar as an SVG document: a terracotta pixel creature with an effort-colored hat
 * (a violet crown for the main loop), a pennant on a stick while it runs, X eyes when it failed,
 * and 0.8 opacity once it is done, stopped or aborted.
 */
export function critterSvg(o: { main?: boolean; hat?: string; state?: CritterState; faded?: boolean; size?: number }): string {
  const main = o.main === true
  const hat = /^#[0-9a-f]{6}$/i.test(o.hat ?? '') ? (o.hat as string) : NO_EFFORT.hat
  const state: CritterState = o.state ?? 'idle'
  const faded = o.faded === true || state === 'done'
  const size = typeof o.size === 'number' && o.size >= 8 && o.size <= 256 ? Math.round(o.size) : CRITTER_SIZE
  const key = [main ? 'm' : 'a', hat, state, faded ? 'f' : '', size].join('|')
  const hit = critterCache.get(key)
  if (hit !== undefined) return hit
  const rows = [...(main ? CROWN : HAT), ...BODY]
  if (state === 'running') POLE.forEach((p, y) => (rows[y] = rows[y].slice(0, 9) + p.slice(9)))
  const fills: Record<string, string> = {
    H: main ? CRITTER.crown : hat,
    O: CRITTER.outline,
    B: CRITTER.body,
    E: state === 'failed' ? CRITTER.body : CRITTER.eye,
    S: CRITTER.stick,
    P: CRITTER.pennant,
  }
  let rects = ''
  rows.forEach((line, y) => {
    let x = 0
    while (x < 12) {
      const ch = line[x] ?? '.'
      let end = x + 1
      while (end < 12 && line[end] === ch) end++
      if (fills[ch]) rects += `<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${fills[ch]}"/>`
      x = end
    }
  })
  // X eyes: two crossed strokes over each eye
  if (state === 'failed') {
    rects += `<path d="M1.7 4.8 3.3 7.2M3.3 4.8 1.7 7.2M5.7 4.8 7.3 7.2M7.3 4.8 5.7 7.2" stroke="${CRITTER.eye}" stroke-width="0.5"/>`
  }
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 12 12" width="${size}" height="${size}" shape-rendering="crispEdges">` +
    `<g${faded ? ' opacity="0.8"' : ''}>${rects}</g></svg>`
  if (critterCache.size >= 64) critterCache.clear()
  critterCache.set(key, svg)
  return svg
}

